15	// How far ahead budget months are available. Planning past the minimum
16	// keeps a few empty months after the latest allocation, up to a hard cap
17	// so stray far-future data can't create an unbounded number of months.
18	const MIN_MONTHS_AHEAD = 12;
19	const MONTHS_AFTER_LATEST_ALLOCATION = 3;
20	const MAX_MONTHS_AHEAD = 60;
21	
22	export function getBudgetType() {
23	  const meta = sheet.get().meta();
24	  return meta.budgetType || 'envelope';
25	}
26	
27	export function getBudgetRange(
28	  start: string,
29	  end: string,
30	  latestAllocatedMonth?: string | null,
31	) {
32	  start = monthUtils.getMonth(start);
33	  end = monthUtils.getMonth(end);
34	
35	  // The start date should never be after the end date. If that
36	  // happened, the month range might be a valid range and weird
37	  // things happen
38	  if (start > end) {
39	    start = end;
40	  }
41	
42	  const maxEnd = monthUtils.addMonths(end, MAX_MONTHS_AHEAD);
43	
44	  // Budgets should exist 3 months before the earliest needed date
45	  // (either the oldest transaction or the current month if no
46	  // transactions yet), and at least a year from the current date.
47	  start = monthUtils.subMonths(start, 3);
48	  end = monthUtils.addMonths(end, MIN_MONTHS_AHEAD);
49	
50	  if (latestAllocatedMonth) {
51	    const plannedEnd = monthUtils.addMonths(
52	      latestAllocatedMonth,
53	      MONTHS_AFTER_LATEST_ALLOCATION,
54	    );
55	    if (plannedEnd > end) {
56	      end = plannedEnd < maxEnd ? plannedEnd : maxEnd;
57	    }
58	  }
59	
60	  return { start, end, range: monthUtils.rangeInclusive(start, end) };
61	}
62	
63	// The latest month with a non-zero amount in the active budget type.
64	// Envelope and tracking amounts are stored separately, so each type
65	// extends its own range.
66	async function getLatestAllocatedMonth(): Promise<string | null> {
67	  const table =
68	    getBudgetType() === 'tracking' ? 'reflect_budgets' : 'zero_budgets';
69	  const row = await db.first<{ month: number | null }>(
70	    `SELECT MAX(b.month) AS month FROM ${table} b
71	     JOIN categories c ON c.id = b.category
72	     WHERE c.tombstone = 0 AND b.amount != 0`,
73	  );
74	  if (!row?.month) {
75	    return null;
76	  }
77	  const month = String(row.month);
78	  return `${month.slice(0, 4)}-${month.slice(4)}`;
79	}
80	
81	// The day range spanning the given months. They aren't guaranteed to be
82	// sorted, so find the first and last explicitly ('YYYY-MM' strings compare
83	// chronologically).
84	function getMonthSpanBounds(months: string[]) {
85	  let firstMonth = months[0];
86	  let lastMonth = months[0];
87	  for (const month of months) {
88	    if (month < firstMonth) {
89	      firstMonth = month;
90	    }
91	    if (month > lastMonth) {
92	      lastMonth = month;
93	    }
94	  }
95	
96	  return {
97	    rangeStart: monthUtils.bounds(firstMonth).start,
98	    rangeEnd: monthUtils.bounds(lastMonth).end,
99	  };
100	}
101	
102	// Computes the spend total for every category in every month within the
103	// given day range using a single grouped query. This is used to seed the
104	// `sum-amount` cells on a cold build so we avoid running one
105	// `SELECT SUM(amount)` query per category per month (which scales as
106	// categories × months and dominates load time for budgets with many years
107	// of data). The filters must match the per-cell query in `createCategory`
108	// exactly so balances stay identical.
109	function getSumAmountsByMonth(
110	  rangeStart: number,
111	  rangeEnd: number,
112	): Map<string, number> {
113	  const rows = db.runQuery<{ month: number; category: string; amount: number }>(
114	    `SELECT t.category AS category,
115	            t.date / 100 AS month,
116	            SUM(t.amount) AS amount
117	       FROM v_transactions_internal_alive t
118	       LEFT JOIN accounts a ON a.id = t.account
119	      WHERE t.date >= ${rangeStart} AND t.date <= ${rangeEnd}
120	        AND t.category IS NOT NULL
121	        AND a.offbudget = 0
122	      GROUP BY t.category, t.date / 100`,
123	    [],
124	    true,
125	  );
126	
127	  const sums = new Map<string, number>();
128	  for (const row of rows) {
129	    sums.set(`${row.month}-${row.category}`, row.amount || 0);
130	  }
131	  return sums;
132	}
133	
134	// Reseeds the `sum-amount` cells for the given months from the same single
135	// grouped query a cold build uses, and returns the names of the cells that
136	// were seeded. Resetting the budget cache recomputes every cell, which would
137	// otherwise run one `SELECT SUM(amount)` per category per month; the caller
138	// skips recomputing these and caches them directly instead.
139	export async function reseedSumAmounts(months: string[]): Promise<string[]> {
140	  if (months.length === 0) {
141	    return [];
142	  }
143	
144	  const { rangeStart, rangeEnd } = getMonthSpanBounds(months);
145	  const sums = getSumAmountsByMonth(rangeStart, rangeEnd);
146	
147	  const { data: groups }: { data: CategoryGroupEntity[] } = await aqlQuery(
148	    q('category_groups').select('*'),
149	  );
150	  const categories = groups.flatMap(group => group.categories);
151	
152	  const seededCells: string[] = [];
153	  for (const month of months) {
154	    const sheetName = monthUtils.sheetForMonth(month);
155	    const dbMonth = parseInt(month.replace('-', ''));
156	
157	    for (const cat of categories) {
158	      const name = resolveName(sheetName, `sum-amount-${cat.id}`);
159	      // A cell the spreadsheet doesn't have stays out of the seed set and is
160	      // left to be recomputed normally.
161	      if (!sheet.get().hasCell(name)) {
162	        continue;
163	      }
164	
165	      sheet.get().load(name, sums.get(`${dbMonth}-${cat.id}`) || 0);
166	      seededCells.push(name);
167	    }
168	  }
169	
170	  return seededCells;
171	}
172	
173	export function createCategory(cat, sheetName, prevSheetName, start, end) {
174	  sheet.get().createDynamic(sheetName, 'sum-amount-' + cat.id, {
175	    initialValue: 0,
176	    run: () => {
177	      // Making this sync is faster!
178	      const rows = db.runQuery<{ amount: number }>(
179	        `SELECT SUM(amount) as amount FROM v_transactions_internal_alive t
180	           LEFT JOIN accounts a ON a.id = t.account
181	         WHERE t.date >= ${start} AND t.date <= ${end}
182	           AND category = '${cat.id}' AND a.offbudget = 0`,
183	        [],
184	        true,
185	      );
186	      const row = rows[0];
187	      const amount = row ? row.amount : 0;
188	      return amount || 0;
189	    },
190	  });
191	
192	  if (getBudgetType() === 'envelope') {
193	    envelopeBudget.createCategory(cat, sheetName, prevSheetName);
194	  } else {
195	    void trackingBudget.createCategory(cat, sheetName, prevSheetName);
196	  }
197	}
198	
199	function handleAccountChange(months, oldValue, newValue) {
200	  if (!oldValue || oldValue.offbudget !== newValue.offbudget) {
201	    const rows = db.runQuery<Pick<db.DbTransaction, 'category'>>(
202	      `
203	        SELECT DISTINCT(category) as category FROM transactions
204	        WHERE acct = ?
205	      `,
206	      [newValue.id],
207	      true,
208	    );
209	
210	    months.forEach(month => {
211	      const sheetName = monthUtils.sheetForMonth(month);
212	
213	      rows.forEach(row => {
214	        sheet
215	          .get()
216	          .recompute(resolveName(sheetName, 'sum-amount-' + row.category));
217	      });
218	    });
219	  }
220	}
221	
222	function handleTransactionChange(transaction, changedFields) {
223	  if (
224	    (changedFields.has('date') ||
225	      changedFields.has('acct') ||
226	      changedFields.has('amount') ||
227	      changedFields.has('category') ||
228	      changedFields.has('tombstone') ||
229	      changedFields.has('isParent')) &&
230	    transaction.date &&
231	    transaction.category
232	  ) {
233	    const month = monthUtils.monthFromDate(db.fromDateRepr(transaction.date));
234	    const sheetName = monthUtils.sheetForMonth(month);
235	
236	    sheet
237	      .get()
238	      .recompute(resolveName(sheetName, 'sum-amount-' + transaction.category));
239	  }
240	}
241	
242	function handleCategoryMappingChange(months, oldValue, newValue) {
243	  months.forEach(month => {
244	    const sheetName = monthUtils.sheetForMonth(month);
245	    if (oldValue) {
246	      sheet
247	        .get()
248	        .recompute(resolveName(sheetName, 'sum-amount-' + oldValue.transferId));
249	    }
250	    sheet
251	      .get()
252	      .recompute(resolveName(sheetName, 'sum-amount-' + newValue.transferId));
253	  });
254	}
255	
256	function handleBudgetMonthChange(budget) {
257	  const sheetName = monthUtils.sheetForMonth(budget.id);
258	  sheet.get().set(`${sheetName}!buffered`, budget.buffered);
259	}
260	
261	function handleBudgetChange(budget) {
262	  if (budget.category) {
263	    const sheetName = monthUtils.sheetForMonth(budget.month.toString());
264	    sheet
265	      .get()
266	      .set(`${sheetName}!budget-${budget.category}`, budget.amount || 0);
267	    sheet
268	      .get()
269	      .set(
270	        `${sheetName}!carryover-${budget.category}`,
271	        budget.carryover === 1 ? true : false,
272	      );
273	    sheet.get().set(`${sheetName}!goal-${budget.category}`, budget.goal);
274	    sheet
275	      .get()
276	      .set(`${sheetName}!long-goal-${budget.category}`, budget.long_goal);
277	  }
278	}
279	
280	export function triggerBudgetChanges(oldValues, newValues) {
281	  const { createdMonths = new Set() } = sheet.get().meta();
282	  const budgetType = getBudgetType();
283	  // Amounts and goals are saved per budget type, and only the active type's
284	  // belong in the sheet. Go by the stored pref, which decides the table the
285	  // budget actions save to.
286	  const budgetTable = budgetActions.getBudgetTable();
287	  sheet.startTransaction();
288	
289	  try {
290	    newValues.forEach((items, table) => {
291	      const old = oldValues.get(table);
292	
293	      items.forEach(newValue => {
294	        const oldValue = old && old.get(newValue.id);
295	
296	        if (table === 'zero_budget_months') {
297	          handleBudgetMonthChange(newValue);
298	        } else if (table === 'zero_budgets' || table === 'reflect_budgets') {
299	          if (table === budgetTable) {
300	            handleBudgetChange(newValue);
301	          }
302	        } else if (table === 'transactions') {
303	          const changed = new Set(
304	            Object.keys(getChangedValues(oldValue || {}, newValue) || {}),
305	          );
306	
307	          if (oldValue) {
308	            handleTransactionChange(oldValue, changed);
309	          }
310	          handleTransactionChange(newValue, changed);
311	        } else if (table === 'category_mapping') {
312	          handleCategoryMappingChange(createdMonths, oldValue, newValue);
313	        } else if (table === 'categories') {
314	          if (budgetType === 'envelope') {
315	            envelopeBudget.handleCategoryChange(
316	              createdMonths,
317	              oldValue,
318	              newValue,
319	            );
320	          } else {
321	            trackingBudget.handleCategoryChange(
322	              createdMonths,
323	              oldValue,
324	              newValue,
325	            );
326	          }
327	        } else if (table === 'category_groups') {
328	          if (budgetType === 'envelope') {
329	            envelopeBudget.handleCategoryGroupChange(
330	              createdMonths,
331	              oldValue,
332	              newValue,
333	            );
334	          } else {
335	            trackingBudget.handleCategoryGroupChange(
336	              createdMonths,
337	              oldValue,
338	              newValue,
339	            );
340	          }
341	        } else if (table === 'accounts') {
342	          handleAccountChange(createdMonths, oldValue, newValue);
343	        }
344	      });
345	    });
346	  } finally {
347	    sheet.endTransaction();
348	  }
349	}
350	
351	export async function doTransfer(categoryIds, transferId) {
352	  const { createdMonths: months } = sheet.get().meta();
353	
354	  [...months].forEach(month => {
355	    const totalValue = categoryIds
356	      .map(id => {
357	        return budgetActions.getBudget({ month, category: id });
358	      })
359	      .reduce((total, value) => total + value, 0);
360	
361	    const transferValue = budgetActions.getBudget({
362	      month,
363	      category: transferId,
364	    });
365	
366	    void budgetActions.setBudget({
367	      month,
368	      category: transferId,
369	      amount: totalValue + transferValue,
370	    });
371	  });
372	}
373	
374	export async function createBudget(months) {
375	  const { data: groups }: { data: CategoryGroupEntity[] } = await aqlQuery(
376	    q('category_groups').select('*'),
377	  );
378	  const categories = groups.flatMap(group => group.categories);
379	
380	  sheet.startTransaction();
381	  const meta = sheet.get().meta();
382	  meta.createdMonths = meta.createdMonths || new Set();
383	
384	  const budgetType = getBudgetType();
385	
386	  if (budgetType === 'envelope') {
387	    envelopeBudget.createBudget(meta, categories, months);
388	  }
389	
390	  // Only months that don't already exist need to be created and seeded.
391	  const monthsToCreate = months.filter(month => !meta.createdMonths.has(month));
392	
393	  // Spend totals for every category in the months being created, computed
394	  // once via a single grouped query and used to seed the `sum-amount` cells so
395	  // they don't each run their own query. Scoped to the uncached month span so
396	  // extending the budget horizon doesn't rescan the entire transaction
397	  // history, and loaded lazily so warm loads never touch the database here.
398	  let sumAmounts: Map<string, number> | null = null;
399	  const getSumAmounts = () => {
400	    if (!sumAmounts) {
401	      const { rangeStart, rangeEnd } = getMonthSpanBounds(monthsToCreate);
402	      sumAmounts = getSumAmountsByMonth(rangeStart, rangeEnd);
403	    }
404	    return sumAmounts;
405	  };
406	  const seededCells: string[] = [];
407	
408	  monthsToCreate.forEach(month => {
409	    const prevMonth = monthUtils.prevMonth(month);
410	    const { start, end } = monthUtils.bounds(month);
411	    const sheetName = monthUtils.sheetForMonth(month);
412	    const prevSheetName = monthUtils.sheetForMonth(prevMonth);
413	    const dbMonth = parseInt(month.replace('-', ''));
414	
415	    categories.forEach(cat => {
416	      // Seed the spend total before creating the dynamic cell so the cell
417	      // skips its per-category query. Only happens on a cold build, when
418	      // the value hasn't been restored from cache.
419	      const sumCell = `sum-amount-${cat.id}`;
420	      if (sheet.get().getCellValueLoose(sheetName, sumCell) == null) {
421	        const name = resolveName(sheetName, sumCell);
422	        sheet
423	          .get()
424	          .load(name, getSumAmounts().get(`${dbMonth}-${cat.id}`) || 0);
425	        seededCells.push(name);
426	      }
427	      createCategory(cat, sheetName, prevSheetName, start, end);
428	    });
429	    groups.forEach(group => {
430	      if (budgetType === 'envelope') {
431	        envelopeBudget.createCategoryGroup(group, sheetName);
432	      } else {
433	        trackingBudget.createCategoryGroup(group, sheetName);
434	      }
435	    });
436	
437	    if (budgetType === 'envelope') {
438	      envelopeBudget.createSummary(
439	        groups,
440	        categories,
441	        prevSheetName,
442	        sheetName,
443	      );
444	    } else {
445	      trackingBudget.createSummary(groups, sheetName);
446	    }
447	
448	    meta.createdMonths.add(month);
449	  });
450	
451	  sheet.get().setMeta(meta);
452	  sheet.endTransaction();
453	
454	  // Persist the seeded spend totals to the cache. Because they were loaded
455	  // directly (rather than recomputed) they aren't part of the computation
456	  // queue that normally gets cached, so without this a warm load would have
457	  // to recompute them. The cells already hold their final values here.
458	  if (seededCells.length > 0) {
459	    sheet.get().saveCachedCells(seededCells);
460	  }
461	
462	  // Wait for the spreadsheet to finish computing. Normally this won't
463	  // do anything (as values are cached) but on first run this need to
464	  // show the loading screen while it initially sets up.
465	  await sheet.waitOnSpreadsheet();
466	}
467	
468	export async function createAllBudgets() {
469	  const earliestTransaction = await db.first<db.DbTransaction>(
470	    'SELECT * FROM transactions WHERE isChild=0 AND date IS NOT NULL ORDER BY date ASC LIMIT 1',
471	  );
472	  const earliestDate =
473	    earliestTransaction && db.fromDateRepr(earliestTransaction.date);
474	  const currentMonth = monthUtils.currentMonth();
475	
476	  // Get the range based off of the earliest transaction and the
477	  // current month. If no transactions currently exist the current
478	  // month is also used as the starting month
479	  const { start, end, range } = getBudgetRange(
480	    earliestDate || currentMonth,
481	    currentMonth,
482	    await getLatestAllocatedMonth(),
483	  );
484	
485	  const meta = sheet.get().meta();
486	  const createdMonths = meta.createdMonths || new Set();
487	  const newMonths = range.filter(m => !createdMonths.has(m));
488	
489	  if (newMonths.length > 0) {
490	    await createBudget(range);
491	  }
492	
493	  // The range only grows while the budget is open, so every created month
494	  // stays reachable. Clearing allocations shrinks it on the next load.
495	  let lastMonth = end;
496	  for (const month of sheet.get().meta().createdMonths) {
497	    if (month > lastMonth) {
498	      lastMonth = month;
499	    }
500	  }
501	
502	  return { start, end: lastMonth };
503	}
504	
505	export async function setType(type) {
506	  const meta = sheet.get().meta();
507	  if (type === meta.budgetType) {
508	    return;
509	  }
510	
511	  meta.budgetType = type;
512	  meta.createdMonths = new Set();
513	
514	  // Go through and force all the cells to be recomputed
515	  const nodes = sheet.get().getNodes();
516	  db.transaction(() => {
517	    for (const name of nodes.keys()) {
518	      const [sheetName, cellName] = name.split('!');
519	      if (sheetName.match(/^budget\d+/)) {
520	        sheet.get().deleteCell(sheetName, cellName);
521	      }
522	    }
523	  });
524	
525	  sheet.get().startCacheBarrier();
526	  // The cache still holds the old type's cells. Goals and other inputs are
527	  // never recomputed, so the next load from the cache would restore them.
528	  sheet.clearCache();
529	  await sheet.loadUserBudgets(db);
530	  const bounds = await createAllBudgets();
531	  sheet.get().endCacheBarrier();
532	
533	  return bounds;
534	}
