473	async function getAverageMonths({
474	  month,
475	  maxMonths,
476	  categoryId,
477	}: {
478	  month: string;
479	  maxMonths: number;
480	  categoryId: string;
481	}): Promise<string[]> {
482	  const firstMonth = getAverageStartMonth(month);
483	  const firstActivityMonth = await getFirstActivityMonth({
484	    categoryId,
485	    endMonth: firstMonth,
486	  });
487	  const months: string[] = [];
488	  let prevMonth = firstMonth;
489	
490	  for (let l = 0; l < maxMonths; l++) {
491	    if (firstActivityMonth != null && prevMonth < firstActivityMonth) {
492	      break;
493	    }
494	
495	    months.push(prevMonth);
496	    prevMonth = monthUtils.prevMonth(prevMonth);
497	  }
498	
499	  return months;
500	}
