502	function getAverageStartMonth(month: string): string {
503	  const prevMonth = monthUtils.prevMonth(month);
504	
505	  if (prevMonth >= monthUtils.currentMonth()) {
506	    return monthUtils.prevMonth(monthUtils.currentMonth());
507	  }
508	
509	  return prevMonth;
510	}
