519	  const table = getBudgetTable();
520	  const endDbMonth = dbMonth(endMonth);
521	  const firstActivity = await db.first<{ month: number | null }>(
522	    `SELECT MIN(month) AS month
523	       FROM (
524	         SELECT month
525	           FROM ${table}
526	          WHERE category = ? AND month <= ?
527	         UNION ALL
528	         SELECT CAST(t.date / 100 AS INTEGER) AS month
529	           FROM v_transactions_internal_alive t
530	           LEFT JOIN accounts a ON a.id = t.account
531	          WHERE t.category = ?
532	            AND CAST(t.date / 100 AS INTEGER) <= ?
533	            AND a.offbudget = 0
534	       )`,
535	    [categoryId, endDbMonth, categoryId, endDbMonth],
536	  );
537	
538	  return firstActivity?.month == null
539	    ? null
540	    : monthFromDbMonth(firstActivity.month);
541	}
