575	export async function coverOverspending({
576	  month,
577	  to,
578	  from,
579	  amount,
580	  currencyCode,
581	}: {
582	  month: string;
583	  to: CategoryEntity['id'] | 'to-budget';
584	  from: CategoryEntity['id'] | 'to-budget' | 'overbudgeted';
585	  amount?: IntegerAmount;
586	  currencyCode: string;
587	}): Promise<void> {
588	  const sheetName = monthUtils.sheetForMonth(month);
589	  const toBudgeted = await getSheetValue(sheetName, 'budget-' + to);
590	  const leftoverFrom = await getSheetValue(
591	    sheetName,
592	    from === 'to-budget' ? 'to-budget' : 'leftover-' + from,
593	  );
594	
595	  // Cover provided amount (can be partial) or full overspending amount.
596	  const amountToCover = amount
597	    ? // Covering in the app provides a positive amount to cover so we invert it here
598	      -amount
599	    : await getSheetValue(sheetName, 'leftover-' + to);
600	
601	  if (amountToCover >= 0 || leftoverFrom <= 0) {
602	    return;
603	  }
604	
605	  // Don't go over the leftover amount of the covering category
606	  const coverableAmount = Math.min(Math.abs(amountToCover), leftoverFrom);
607	
608	  await batchMessages(async () => {
609	    // If we are covering it from the to be budgeted amount, ignore this
610	    if (from !== 'to-budget') {
611	      const fromBudgeted = await getSheetValue(sheetName, 'budget-' + from);
612	      await setBudget({
613	        category: from,
614	        month,
615	        amount: fromBudgeted - coverableAmount,
616	      });
617	    }
618	
619	    await setBudget({
620	      category: to,
621	      month,
622	      amount: toBudgeted + coverableAmount,
623	    });
624	
625	    await addMovementNotes({
626	      month,
627	      amount: coverableAmount,
628	      to,
629	      from,
630	      currencyCode,
631	    });
632	  });
633	}
