184	    dependencies: [`${sheetName}!buffered`, `${sheetName}!buffered-auto`],
185	    run: (man, auto) => {
186	      if (man !== 0) {
187	        return man;
188	      }
189	      return auto;
190	    },
191	  });
192	
193	  sheet.get().createDynamic(sheetName, 'to-budget', {
194	    initialValue: 0,
