240	export function handleCategoryChange(months, oldValue, newValue) {
241	  // Build list of cells and dependencies that need updated
242	  function getDeps(sheetName, prevSheetName, groupId, cat) {
243	    const deps: Array<[string, string[]]> = [
244	      [`group-sum-amount-${groupId}`, [`sum-amount-${cat.id}`]],
245	      [`group-budget-${groupId}`, [`budget-${cat.id}`]],
246	      [`group-leftover-${groupId}`, [`leftover-${cat.id}`]],
247	    ];
248	
249	    if (cat.is_income) {
250	      deps.push([
251	        'buffered-auto',
252	        [
253	          `${sheetName}!sum-amount-${cat.id}`,
254	          `${sheetName}!carryover-${cat.id}`,
255	        ],
256	      ]);
257	    } else {
258	      deps.push([
259	        'last-month-overspent',
260	        [
261	          `${prevSheetName}!leftover-${cat.id}`,
262	          `${prevSheetName}!carryover-${cat.id}`,
263	        ],
264	      ]);
265	    }
266	
267	    return deps;
268	  }
269	
270	  function addDeps(sheetName, prevSheetName, groupId, cat) {
271	    getDeps(sheetName, prevSheetName, groupId, cat).forEach(
272	      ([cellName, deps]) => {
273	        sheet.get().addDependencies(sheetName, cellName, deps);
274	      },
275	    );
276	  }
277	
278	  function removeDeps(sheetName, prevSheetName, groupId, cat) {
279	    getDeps(sheetName, prevSheetName, groupId, cat).forEach(
280	      ([cellName, deps]) => {
281	        sheet.get().removeDependencies(sheetName, cellName, deps);
282	      },
283	    );
284	  }
285	
286	  if (oldValue && oldValue.tombstone === 0 && newValue.tombstone === 1) {
287	    months.forEach(month => {
288	      const prevSheetName = monthUtils.sheetForMonth(
289	        monthUtils.prevMonth(month),
290	      );
291	      const sheetName = monthUtils.sheetForMonth(month);
292	
293	      removeDeps(sheetName, prevSheetName, newValue.cat_group, newValue);
294	    });
295	  } else if (
296	    newValue.tombstone === 0 &&
297	    (!oldValue || oldValue.tombstone === 1)
298	  ) {
299	    createBlankCategory(newValue, months);
300	
301	    months.forEach(month => {
302	      const prevMonth = monthUtils.prevMonth(month);
303	      const prevSheetName = monthUtils.sheetForMonth(prevMonth);
304	      const sheetName = monthUtils.sheetForMonth(month);
305	      const { start, end } = monthUtils.bounds(month);
306	
307	      createCategoryFromBase(newValue, sheetName, prevSheetName, start, end);
308	
309	      addDeps(sheetName, prevSheetName, newValue.cat_group, newValue);
310	    });
311	  } else if (oldValue && oldValue.cat_group !== newValue.cat_group) {
312	    // The category moved so we need to update the dependencies
313	    months.forEach(month => {
314	      const prevSheetName = monthUtils.sheetForMonth(
315	        monthUtils.prevMonth(month),
316	      );
317	      const sheetName = monthUtils.sheetForMonth(month);
318	
319	      removeDeps(sheetName, prevSheetName, oldValue.cat_group, newValue);
320	      addDeps(sheetName, prevSheetName, newValue.cat_group, newValue);
321	    });
322	  }
323	}
