63	// The latest month with a non-zero amount in the active budget type.
64	// Envelope and tracking amounts are stored separately, so each type
65	// extends its own range.
66	async function getLatestAllocatedMonth(): Promise<string | null> {
67	  const table =
68	    getBudgetType() === 'tracking' ? 'reflect_budgets' : 'zero_budgets';
69	  const row = await db.first<{ month: number | null }>(
70	    `SELECT MAX(b.month) AS month FROM ${table} b
71	     JOIN categories c ON c.id = b.category
72	     WHERE c.tombstone = 0 AND b.amount != 0`,
73	  );
74	  if (!row?.month) {
75	    return null;
76	  }
77	  const month = String(row.month);
78	  return `${month.slice(0, 4)}-${month.slice(4)}`;
79	}
