280	export function triggerBudgetChanges(oldValues, newValues) {
281	  const { createdMonths = new Set() } = sheet.get().meta();
282	  const budgetType = getBudgetType();
283	  // Amounts and goals are saved per budget type, and only the active type's
284	  // belong in the sheet. Go by the stored pref, which decides the table the
285	  // budget actions save to.
286	  const budgetTable = budgetActions.getBudgetTable();
287	  sheet.startTransaction();
288	
289	  try {
290	    newValues.forEach((items, table) => {
291	      const old = oldValues.get(table);
292	
293	      items.forEach(newValue => {
294	        const oldValue = old && old.get(newValue.id);
295	
296	        if (table === 'zero_budget_months') {
297	          handleBudgetMonthChange(newValue);
298	        } else if (table === 'zero_budgets' || table === 'reflect_budgets') {
299	          if (table === budgetTable) {
300	            handleBudgetChange(newValue);
301	          }
302	        } else if (table === 'transactions') {
303	          const changed = new Set(
304	            Object.keys(getChangedValues(oldValue || {}, newValue) || {}),
305	          );
306	
307	          if (oldValue) {
308	            handleTransactionChange(oldValue, changed);
309	          }
310	          handleTransactionChange(newValue, changed);
311	        } else if (table === 'category_mapping') {
312	          handleCategoryMappingChange(createdMonths, oldValue, newValue);
313	        } else if (table === 'categories') {
314	          if (budgetType === 'envelope') {
315	            envelopeBudget.handleCategoryChange(
316	              createdMonths,
317	              oldValue,
318	              newValue,
319	            );
320	          } else {
321	            trackingBudget.handleCategoryChange(
322	              createdMonths,
323	              oldValue,
324	              newValue,
325	            );
326	          }
327	        } else if (table === 'category_groups') {
328	          if (budgetType === 'envelope') {
329	            envelopeBudget.handleCategoryGroupChange(
330	              createdMonths,
331	              oldValue,
332	              newValue,
333	            );
334	          } else {
335	            trackingBudget.handleCategoryGroupChange(
336	              createdMonths,
337	              oldValue,
338	              newValue,
339	            );
340	          }
341	        } else if (table === 'accounts') {
342	          handleAccountChange(createdMonths, oldValue, newValue);
343	        }
344	      });
345	    });
346	  } finally {
347	    sheet.endTransaction();
348	  }
349	}
