351	export async function doTransfer(categoryIds, transferId) {
352	  const { createdMonths: months } = sheet.get().meta();
353	
354	  [...months].forEach(month => {
355	    const totalValue = categoryIds
356	      .map(id => {
357	        return budgetActions.getBudget({ month, category: id });
358	      })
359	      .reduce((total, value) => total + value, 0);
360	
361	    const transferValue = budgetActions.getBudget({
362	      month,
363	      category: transferId,
364	    });
365	
366	    void budgetActions.setBudget({
367	      month,
368	      category: transferId,
369	      amount: totalValue + transferValue,
370	    });
371	  });
372	}
