468	export async function createAllBudgets() {
469	  const earliestTransaction = await db.first<db.DbTransaction>(
470	    'SELECT * FROM transactions WHERE isChild=0 AND date IS NOT NULL ORDER BY date ASC LIMIT 1',
471	  );
472	  const earliestDate =
473	    earliestTransaction && db.fromDateRepr(earliestTransaction.date);
474	  const currentMonth = monthUtils.currentMonth();
475	
476	  // Get the range based off of the earliest transaction and the
477	  // current month. If no transactions currently exist the current
478	  // month is also used as the starting month
479	  const { start, end, range } = getBudgetRange(
480	    earliestDate || currentMonth,
481	    currentMonth,
482	    await getLatestAllocatedMonth(),
483	  );
484	
485	  const meta = sheet.get().meta();
486	  const createdMonths = meta.createdMonths || new Set();
487	  const newMonths = range.filter(m => !createdMonths.has(m));
488	
489	  if (newMonths.length > 0) {
490	    await createBudget(range);
491	  }
492	
493	  // The range only grows while the budget is open, so every created month
494	  // stays reachable. Clearing allocations shrinks it on the next load.
495	  let lastMonth = end;
496	  for (const month of sheet.get().meta().createdMonths) {
497	    if (month > lastMonth) {
498	      lastMonth = month;
499	    }
500	  }
501	
502	  return { start, end: lastMonth };
503	}
504	
505	export async function setType(type) {
506	  const meta = sheet.get().meta();
507	  if (type === meta.budgetType) {
508	    return;
509	  }
510	
511	  meta.budgetType = type;
512	  meta.createdMonths = new Set();
513	
514	  // Go through and force all the cells to be recomputed
515	  const nodes = sheet.get().getNodes();
516	  db.transaction(() => {
517	    for (const name of nodes.keys()) {
518	      const [sheetName, cellName] = name.split('!');
519	      if (sheetName.match(/^budget\d+/)) {
520	        sheet.get().deleteCell(sheetName, cellName);
521	      }
522	    }
523	  });
524	
525	  sheet.get().startCacheBarrier();
526	  // The cache still holds the old type's cells. Goals and other inputs are
527	  // never recomputed, so the next load from the cache would restore them.
528	  sheet.clearCache();
529	  await sheet.loadUserBudgets(db);
530	  const bounds = await createAllBudgets();
531	  sheet.get().endCacheBarrier();
532	
533	  return bounds;
534	}
