420	// Average weekly spending (signed, like `sum-amount`) over the `numWeeks`
421	// complete weeks before `month`. See `getWeeklyAverageWindow` for the exact
422	// window. Weeks before the category's first transaction are left out.
423	// Not rounded: callers multiply it by the weekday count first, so rounding
424	// here would drift the monthly amount by up to a few minor units.
425	export async function getCategoryWeeklyAverage({
426	  month,
427	  numWeeks,
428	  categoryId,
429	}: {
430	  month: string;
431	  numWeeks: number;
432	  categoryId: string;
433	}): Promise<number> {
434	  const fullWindow = getWeeklyAverageWindow({
435	    month,
436	    numWeeks,
437	    today: monthUtils.currentDay(),
438	  });
439	
440	  const firstActivity = await db.first<{ date: number | null }>(
441	    `SELECT MIN(t.date) AS date
442	       FROM v_transactions_internal_alive t
443	       LEFT JOIN accounts a ON a.id = t.account
444	      WHERE t.category = ?
445	        AND t.date <= ?
446	        AND a.offbudget = 0`,
447	    [categoryId, db.toDateRepr(fullWindow.end)],
448	  );
449	  const window = trimWeeklyAverageWindow(
450	    fullWindow,
451	    firstActivity?.date == null ? null : db.fromDateRepr(firstActivity.date),
452	  );
453	  if (window == null) {
454	    return 0;
455	  }
456	
457	  // Same filters as the `sum-amount` cells so weekly and monthly averages
458	  // agree on which transactions count.
459	  const total = await db.first<{ amount: number | null }>(
460	    `SELECT SUM(t.amount) AS amount
461	       FROM v_transactions_internal_alive t
462	       LEFT JOIN accounts a ON a.id = t.account
463	      WHERE t.category = ?
464	        AND t.date >= ?
465	        AND t.date <= ?
466	        AND a.offbudget = 0`,
467	    [categoryId, db.toDateRepr(window.start), db.toDateRepr(window.end)],
468	  );
469	
470	  return safeNumber(total?.amount ?? 0) / window.numWeeks;
471	}
