643	}): Promise<void> {
644	  const sheetName = monthUtils.sheetForMonth(month);
645	  const leftover = await getSheetValue(sheetName, 'to-budget');
646	  amount = Math.max(Math.min(amount, leftover), 0);
647	
648	  const budgeted = await getSheetValue(sheetName, 'budget-' + category);
649	  await setBudget({ category, month, amount: budgeted + amount });
650	}
