652	export async function coverOverbudgeted({
653	  month,
654	  category,
655	  amount,
656	  currencyCode,
657	}: {
658	  month: string;
659	  category: string;
660	  amount?: IntegerAmount;
661	  currencyCode: string;
662	}): Promise<void> {
663	  const sheetName = monthUtils.sheetForMonth(month);
664	  const categoryBudget = await getSheetValue(sheetName, 'budget-' + category);
665	  const categoryLeftover = await getSheetValue(
666	    sheetName,
667	    'leftover-' + category,
668	  );
669	
670	  // Cover provided amount (can be partial) or full overbudgeted amount.
671	  const amountToCover = amount
672	    ? // Covering in the app provides a positive amount to cover so we invert it here
673	      -amount
674	    : await getSheetValue(sheetName, 'to-budget');
675	
676	  if (amountToCover >= 0 || categoryLeftover <= 0) {
677	    return;
678	  }
679	
680	  // Don't exceed the available balance of the covering category.
681	  const coverableAmount = Math.min(Math.abs(amountToCover), categoryLeftover);
682	
683	  await batchMessages(async () => {
684	    await setBudget({
685	      category,
686	      month,
687	      amount: categoryBudget - coverableAmount,
688	    });
689	
690	    await addMovementNotes({
691	      month,
692	      amount: coverableAmount,
693	      from: category,
694	      to: 'overbudgeted',
695	      currencyCode,
696	    });
697	  });
698	}
