700	export async function transferCategory({
701	  month,
702	  amount,
703	  from,
704	  to,
705	  currencyCode,
706	}: {
707	  month: string;
708	  amount: number;
709	  to: CategoryEntity['id'] | 'to-budget';
710	  from: CategoryEntity['id'] | 'to-budget';
711	  currencyCode: string;
712	}): Promise<void> {
713	  const sheetName = monthUtils.sheetForMonth(month);
714	  const fromBudgeted = await getSheetValue(sheetName, 'budget-' + from);
715	
716	  await batchMessages(async () => {
717	    await setBudget({ category: from, month, amount: fromBudgeted - amount });
718	
719	    // If we are simply moving it back into available cash to budget,
720	    // don't do anything else
721	    if (to !== 'to-budget') {
722	      const toBudgeted = await getSheetValue(sheetName, 'budget-' + to);
723	      await setBudget({ category: to, month, amount: toBudgeted + amount });
724	    }
725	
726	    await addMovementNotes({
727	      month,
728	      amount,
729	      to,
730	      from,
731	      currencyCode,
732	    });
733	  });
734	}
