736	export async function copyUntilYearEnd({
737	  month,
738	  category,
739	}: {
740	  month: string;
741	  category: string;
742	}): Promise<void> {
743	  const amount = await getSheetValue(
744	    monthUtils.sheetForMonth(month),
745	    'budget-' + category,
746	  );
747	
748	  const yearEnd = monthUtils.getYearEnd(month);
749	  const { createdMonths } = sheet.get().meta();
750	  const futureMonths = [...(createdMonths as Set<string>)]
751	    .filter(m => m > month && m <= yearEnd)
752	    .sort();
753	
754	  await batchMessages(async () => {
755	    for (const futureMonth of futureMonths) {
756	      void setBudget({ category, month: futureMonth, amount });
757	    }
758	  });
759	}
