784	async function addMovementNotes({
785	  month,
786	  amount,
787	  to,
788	  from,
789	  currencyCode,
790	}: {
791	  month: string;
792	  amount: number;
793	  to: CategoryEntity['id'] | 'to-budget' | 'overbudgeted';
794	  from: CategoryEntity['id'] | 'to-budget';
795	  currencyCode: string;
796	}) {
797	  const displayAmount = integerToCurrencyWithDecimal(amount, currencyCode);
798	
799	  const monthBudgetNotesId = `budget-${month}`;
800	  const existingMonthBudgetNotes = addNewLine(
801	    db.firstSync<Pick<db.DbNote, 'note'>>(
802	      `SELECT n.note FROM notes n WHERE n.id = ?`,
803	      [monthBudgetNotesId],
804	    )?.note,
805	  );
806	
807	  const locale = getLocale(await asyncStorage.getItem('language'));
808	  const displayDay = monthUtils.format(
809	    monthUtils.currentDate(),
810	    'MMMM dd',
811	    locale,
812	  );
813	  const categories = await db.getCategories(
814	    [from, to].filter(c => c !== 'to-budget' && c !== 'overbudgeted'),
815	  );
816	
817	  const fromCategoryName =
818	    from === 'to-budget'
819	      ? 'To Budget'
820	      : categories.find(c => c.id === from)?.name;
821	
822	  const toCategoryName =
823	    to === 'to-budget'
824	      ? 'To Budget'
825	      : to === 'overbudgeted'
826	        ? 'Overbudgeted'
827	        : categories.find(c => c.id === to)?.name;
828	
829	  const note = `Reassigned ${displayAmount} from ${fromCategoryName} → ${toCategoryName} on ${displayDay}`;
830	
831	  await db.update('notes', {
832	    id: monthBudgetNotesId,
833	    note: `${existingMonthBudgetNotes}- ${note}`,
834	  });
835	}
