332	async function updateCategory(category: CategoryEntity): Promise<void> {
333	  try {
334	    // The API types `fields` as a Partial, and db.update() only writes the
335	    // keys it is given, so a partial that omits `name` must stay omitted
336	    // rather than being trimmed into a TypeError (#8857).
337	    if (category.group !== undefined) {
338	      if (!category.group) {
339	        throw APIError('Updating a category: groupId is required');
340	      }
341	
342	      const existingGroup = await db.first<{ id: string }>(
343	        `SELECT id FROM category_groups
344	       WHERE id = ? AND tombstone = 0`,
345	        [category.group],
346	      );
347	
348	      if (!existingGroup) {
349	        throw APIError('Updating a category: category group does not exist');
350	      }
351	    }
352	
353	    const payload = {
354	      ...category,
355	      ...(category.name !== undefined && {
356	        name: category.name.trim(),
357	      }),
358	    };
359	
360	    const update = categoryModel.toDb(payload, { update: true });
361	
362	    const hasWritableField = Object.keys(update).some(key => key !== 'id');
363	
364	    if (!hasWritableField) {
365	      throw APIError('No fields to update');
366	    }
367	
368	    await db.updateCategory(update);
369	  } catch (e) {
370	    if (
371	      e instanceof Error &&
372	      e.message.toLowerCase().includes('unique constraint')
373	    ) {
374	      throw new Error(
375	        `A category with the name "${category.name}" already exists.`,
376	        { cause: e },
377	      );
378	    }
379	    throw e;
380	  }
381	}
