399	  transferId,
400	}: {
401	  id: CategoryEntity['id'];
402	  transferId?: CategoryEntity['id'] | null;
403	}): Promise<void> {
404	  await batchMessages(async () => {
405	    const row = await db.first<Pick<db.DbCategory, 'is_income'>>(
406	      'SELECT is_income FROM categories WHERE id = ?',
407	      [id],
408	    );
409	    if (!row) {
410	      throw new Error(`Category with id ${id} not found.`);
411	    }
412	
413	    const transfer =
414	      transferId &&
415	      (await db.first<Pick<db.DbCategory, 'is_income'>>(
416	        'SELECT is_income FROM categories WHERE id = ?',
417	        [transferId],
418	      ));
419	
420	    if (transferId && !transfer) {
421	      throw new Error(`Transfer category with id ${transferId} not found.`);
422	    } else if (
423	      transferId &&
424	      row &&
425	      transfer &&
426	      row.is_income !== transfer.is_income
427	    ) {
428	      throw new Error('Cannot transfer between income and expense categories.');
429	    }
430	
431	    // Update spreadsheet values if it's an expense category
432	    // TODO: We should do this for income too if it's a tracking budget
433	    if (row.is_income === 0) {
434	      if (transferId) {
