494	
495	    deps = deps.map(dep => {
496	      if (!unresolveName(dep).sheet) {
497	        return resolveName(sheetName, dep);
498	      }
499	      return dep;
500	    });
501	
502	    const node = this.getNode(name);
503	
504	    node._dependencies = (node._dependencies || []).filter(
505	      dep => deps.indexOf(dep) === -1,
506	    );
507	
508	    deps.forEach(dep => {
509	      this.graph.removeEdge(dep, name);
510	    });
511	    this.recompute(name);
512	  }
513	
514	  _markDirty(name) {
515	    this.dirtyCells.push(name);
516	  }
517	
518	  triggerDatabaseChanges(oldValues, newValues) {
519	    const tables = new Set([...oldValues.keys(), ...newValues.keys()]);
520	
521	    this.startTransaction();
522	    // TODO: Create an index of deps so we don't have to iterate
523	    // across all nodes
524	    this.nodes.forEach(node => {
525	      if (
526	        node.sql &&
527	        node.sql.state.dependencies.some(dep => tables.has(dep))
528	      ) {
529	        this._markDirty(node.name);
530	      }
531	    });
532	    this.endTransaction();
533	  }
