1	// @ts-strict-ignore
2	import { captureBreadcrumb } from '#platform/exceptions';
3	import { logger } from '#platform/server/log';
4	import type { Database } from '#platform/server/sqlite';
5	import * as sqlite from '#platform/server/sqlite';
6	import { sheetForMonth } from '#shared/months';
7	import * as Platform from '#shared/platform';
8	
9	import type * as DbModule from './db';
10	import type {
11	  DbPreference,
12	  DbReflectBudget,
13	  DbZeroBudget,
14	  DbZeroBudgetMonth,
15	} from './db';
16	import { Spreadsheet } from './spreadsheet/spreadsheet';
17	import { resolveName } from './spreadsheet/util';
18	
19	let globalSheet: Spreadsheet;
20	let globalOnChange;
21	let globalCacheDb;
22	let globalCacheTarget;
23	
24	export function get(): Spreadsheet {
25	  return globalSheet;
26	}
27	
28	// Prepared once per database: a cold build writes hundreds of thousands of
29	// rows, and preparing the statement for each one dominated the write.
30	const cacheInsertStatements = new WeakMap();
31	
32	async function updateSpreadsheetCache(rawDb, names: string[]) {
33	  let insert = cacheInsertStatements.get(rawDb);
34	  if (!insert) {
35	    insert = sqlite.prepare(
36	      rawDb,
37	      'INSERT OR REPLACE INTO kvcache (key, value) VALUES (?, ?)',
38	    );
39	    cacheInsertStatements.set(rawDb, insert);
40	  }
41	
42	  sqlite.transaction(rawDb, () => {
43	    names.forEach(name => {
44	      const node = globalSheet._getNode(name);
45	
46	      // Don't cache query nodes yet
47	      if (node.sql == null) {
48	        sqlite.runQuery(rawDb, insert, [name, JSON.stringify(node.value)]);
49	      }
50	    });
51	  });
52	}
53	
54	function setCacheStatus(
55	  mainDb: Database,
56	  cacheDb: Database,
57	  { clean }: { clean: boolean },
58	) {
59	  if (clean) {
60	    // Generate random number and stick in both places
61	    const num = Math.random() * 10000000;
62	    sqlite.runQuery(
63	      cacheDb,
64	      'INSERT OR REPLACE INTO kvcache_key (id, key) VALUES (1, ?)',
65	      [num],
66	    );
67	
68	    if (mainDb) {
69	      sqlite.runQuery(
70	        mainDb,
71	        'INSERT OR REPLACE INTO kvcache_key (id, key) VALUES (1, ?)',
72	        [num],
73	      );
74	    }
75	  } else {
76	    sqlite.runQuery(cacheDb, 'DELETE FROM kvcache_key');
77	  }
78	}
79	
80	function isCacheDirty(mainDb: Database, cacheDb: Database): boolean {
81	  let rows = sqlite.runQuery<{ key?: number }>(
82	    cacheDb,
83	    'SELECT key FROM kvcache_key WHERE id = 1',
84	    [],
85	    true,
86	  );
87	  const num = rows.length === 0 ? null : rows[0].key;
88	
89	  if (num == null) {
90	    return true;
91	  }
92	
93	  if (mainDb) {
94	    const rows = sqlite.runQuery<{ key?: number }>(
95	      mainDb,
96	      'SELECT key FROM kvcache_key WHERE id = 1',
97	      [],
98	      true,
99	    );
100	    if (rows.length === 0 || rows[0].key !== num) {
101	      return true;
102	    }
103	  }
104	
105	  // Always also check if there is anything in `kvcache`. We ask for one item;
106	  // if we didn't get back anything it's empty so there is no cache
107	  rows = sqlite.runQuery(cacheDb, 'SELECT * FROM kvcache LIMIT 1', [], true);
108	  return rows.length === 0;
109	}
110	
111	export async function loadSpreadsheet(
112	  db,
113	  onSheetChange?,
114	): Promise<Spreadsheet> {
115	  const cacheEnabled = process.env.NODE_ENV !== 'test';
116	  const mainDb = db.getDatabase();
117	  let cacheDb;
118	
119	  if (!Platform.isBrowser && cacheEnabled) {
120	    // Desktop apps use a separate database for the cache. This is because it is
121	    // much more likely to directly work with files on desktop, and this makes
122	    // it a lot clearer what the true filesize of the main db is (and avoid
123	    // copying the cache data around).
124	    const cachePath = db
125	      .getDatabasePath()
126	      .replace(/db\.sqlite$/, 'cache.sqlite');
127	    globalCacheDb = cacheDb = await sqlite.openDatabase(cachePath);
128	
129	    sqlite.execQuery(
130	      cacheDb,
131	      `
132	        CREATE TABLE IF NOT EXISTS kvcache (key TEXT PRIMARY KEY, value TEXT);
133	        CREATE TABLE IF NOT EXISTS kvcache_key (id INTEGER PRIMARY KEY, key REAL)
134	      `,
135	    );
136	  } else {
137	    // All other platforms use the same database for cache
138	    cacheDb = mainDb;
139	  }
140	
141	  let sheet;
142	  globalCacheTarget = cacheEnabled ? cacheDb : null;
143	  if (cacheEnabled) {
144	    sheet = new Spreadsheet(
145	      updateSpreadsheetCache.bind(null, cacheDb),
146	      setCacheStatus.bind(null, mainDb, cacheDb),
147	    );
148	  } else {
149	    sheet = new Spreadsheet();
150	  }
151	
152	  captureBreadcrumb({
153	    message: 'loading spreadsheet',
154	    category: 'server',
155	  });
156	
157	  globalSheet = sheet;
158	  globalOnChange = onSheetChange;
159	
160	  if (onSheetChange) {
161	    sheet.addEventListener('change', onSheetChange);
162	  }
163	
164	  if (cacheEnabled && !isCacheDirty(mainDb, cacheDb)) {
165	    const cachedRows = sqlite.runQuery<{ key?: number; value: string }>(
166	      cacheDb,
167	      'SELECT * FROM kvcache',
168	      [],
169	      true,
170	    );
171	    logger.log(`Loaded spreadsheet from cache (${cachedRows.length} items)`);
172	
173	    for (const row of cachedRows) {
174	      const parsed = JSON.parse(row.value);
175	      sheet.load(row.key, parsed);
176	    }
177	  } else {
178	    logger.log('Loading fresh spreadsheet');
179	    await loadUserBudgets(db);
180	  }
181	
182	  captureBreadcrumb({
183	    message: 'loaded spreadsheet',
184	    category: 'server',
185	  });
186	
187	  return sheet;
188	}
189	
190	export function unloadSpreadsheet(): void {
191	  if (globalSheet) {
192	    // TODO: Should wait for the sheet to finish
193	    globalSheet.unload();
194	    globalSheet = null;
195	  }
196	
197	  if (globalCacheDb) {
198	    sqlite.closeDatabase(globalCacheDb);
199	    globalCacheDb = null;
200	  }
201	  globalCacheTarget = null;
202	}
203	
204	export function clearCache(): void {
205	  if (globalCacheTarget) {
206	    sqlite.runQuery(globalCacheTarget, 'DELETE FROM kvcache');
207	  }
208	}
209	
210	export async function reloadSpreadsheet(db): Promise<Spreadsheet> {
211	  if (globalSheet) {
212	    unloadSpreadsheet();
213	    return loadSpreadsheet(db, globalOnChange);
214	  }
215	}
216	
217	export async function loadUserBudgets(db: typeof DbModule): Promise<void> {
218	  const sheet = globalSheet;
219	
220	  // TODO: Clear out the cache here so make sure future loads of the app
221	  // don't load any extra values that aren't set here
222	
223	  const { value: budgetType = 'envelope' } =
224	    (await db.first<Pick<DbPreference, 'value'>>(
225	      'SELECT value from preferences WHERE id = ?',
226	      ['budgetType'],
227	    )) ?? {};
228	
229	  const table = budgetType === 'tracking' ? 'reflect_budgets' : 'zero_budgets';
230	  const budgets = await db.all<DbReflectBudget | DbZeroBudget>(`
231	      SELECT * FROM ${table} b
232	      LEFT JOIN categories c ON c.id = b.category
233	      WHERE c.tombstone = 0
234	    `);
235	
236	  sheet.startTransaction();
237	
238	  try {
239	    // Load all the budget amounts and carryover values
240	    for (const budget of budgets) {
241	      if (budget.month && budget.category) {
242	        const sheetName = `budget${budget.month}`;
243	        sheet.set(`${sheetName}!budget-${budget.category}`, budget.amount);
244	        sheet.set(
245	          `${sheetName}!carryover-${budget.category}`,
246	          budget.carryover === 1 ? true : false,
247	        );
248	        sheet.set(`${sheetName}!goal-${budget.category}`, budget.goal);
249	        sheet.set(
250	          `${sheetName}!long-goal-${budget.category}`,
251	          budget.long_goal,
252	        );
253	      }
254	    }
255	
256	    // For zero-based budgets, load the buffered amounts
257	    if (budgetType !== 'tracking') {
258	      const budgetMonths = await db.all<DbZeroBudgetMonth>(
259	        'SELECT * FROM zero_budget_months',
260	      );
261	      for (const budgetMonth of budgetMonths) {
262	        const sheetName = sheetForMonth(budgetMonth.id);
263	        sheet.set(`${sheetName}!buffered`, budgetMonth.buffered);
264	      }
265	    }
266	  } finally {
267	    // The query above runs inside the transaction, so a failure would
268	    // otherwise leave it open and wedge the spreadsheet for the session.
269	    sheet.endTransaction();
270	  }
271	}
272	
273	export function getCell(sheet: string, name: string) {
274	  return globalSheet._getNode(resolveName(sheet, name));
275	}
276	
277	export function getCellValue(
278	  sheet: string,
279	  name: string,
280	): string | number | boolean {
281	  return globalSheet.getValue(resolveName(sheet, name));
282	}
283	
284	export function startTransaction(): void {
285	  if (globalSheet) {
286	    globalSheet.startTransaction();
287	  }
288	}
289	
290	export function endTransaction(): void {
291	  if (globalSheet) {
292	    globalSheet.endTransaction();
293	  }
294	}
295	
296	export function waitOnSpreadsheet(): Promise<void> {
297	  return new Promise(resolve => {
298	    if (globalSheet) {
299	      globalSheet.onFinish(resolve);
300	    } else {
301	      resolve(undefined);
302	    }
303	  });
304	}
