23	  function addNode(node) {
24	    edges.set(node, adjacent(node));
25	    incomingEdges.set(node, adjacentIncoming(node));
26	    return graph;
27	  }
28	
29	  function removeIncomingEdges(node) {
30	    const incoming = adjacentIncoming(node);
31	    incomingEdges.set(node, new Set());
32	
33	    const iter = incoming.values();
34	    let cur = iter.next();
35	    while (!cur.done) {
36	      removeEdge(cur.value, node);
37	      cur = iter.next();
38	    }
39	  }
40	
41	  function removeNode(node) {
42	    removeIncomingEdges(node);
43	    edges.delete(node);
44	    incomingEdges.delete(node);
45	    return graph;
46	  }
47	
48	  function adjacent(node) {
49	    return edges.get(node) || new Set();
50	  }
51	
52	  function adjacentIncoming(node) {
53	    return incomingEdges.get(node) || new Set();
54	  }
55	
56	  // Adds an edge from node u to node v.
57	  // Implicitly adds the nodes if they were not already added.
58	  function addEdge(node1, node2) {
59	    addNode(node1);
60	    addNode(node2);
61	    adjacent(node1).add(node2);
62	    adjacentIncoming(node2).add(node1);
63	    return graph;
64	  }
65	
66	  // Removes the edge from node u to node v.
67	  // Does not remove the nodes.
68	  // Does nothing if the edge does not exist.
69	  function removeEdge(node1, node2) {
70	    if (edges.has(node1)) {
71	      adjacent(node1).delete(node2);
72	    }
73	    if (incomingEdges.has(node2)) {
74	      adjacentIncoming(node2).delete(node1);
75	    }
76	    return graph;
77	  }
