79	  function topologicalSort(sourceNodes: string[]) {
80	    const visited = new Set<string>();
81	    const sorted: string[] = [];
82	
83	    sourceNodes.forEach(name => {
84	      if (!visited.has(name)) {
85	        topologicalSortIterable(name, visited, sorted);
86	      }
87	    });
88	
89	    // Nodes are collected in post-order; reversed, that is a topological order.
90	    sorted.reverse();
91	
92	    return sorted;
93	  }
94	
95	  // Uses an explicit stack so long dependency chains can't overflow the call
96	  // stack. Nodes are marked visited on entry so a cycle can't loop forever.
97	  function topologicalSortIterable(
98	    name: string,
99	    visited: Set<string>,
100	    sorted: string[],
101	  ) {
102	    visited.add(name);
103	    const stack = [createStackFrame(name)];
104	
105	    while (stack.length > 0) {
106	      const frame = stack[stack.length - 1];
107	
108	      let next: string | undefined;
109	      while (frame.index < frame.neighbors.length) {
110	        const neighbor = frame.neighbors[frame.index++];
111	        if (!visited.has(neighbor)) {
112	          next = neighbor;
113	          break;
114	        }
115	      }
116	
117	      if (next !== undefined) {
118	        visited.add(next);
119	        stack.push(createStackFrame(next));
120	      } else {
121	        stack.pop();
122	        sorted.push(frame.value);
123	      }
124	    }
125	  }
