132	  function generateDOT() {
133	    const edgeStrings = [];
134	    edges.forEach(function (adj, edge) {
135	      if (adj.length !== 0) {
136	        edgeStrings.push(`${edge} -> {${adj.join(',')}}`);
137	      }
138	    });
139	
140	    return `
141	    digraph G {
142	      ${edgeStrings.join('\n').replace(/!/g, '_')}
143	    }
144	    `;
145	  }
146	
147	  return graph;
148	}
