export const applyMessages = sequential(_applyMessages);

// Receiving the batch's latest timestamp inside the transaction advances
// the clock once per batch and includes it in the saved `messages_clock`
// row. If the transaction fails, the clock is restored along with it.
function receiveInTransaction(
  messages: Message[],
  applyInTransaction: () => void,
) {
  let latest: Timestamp | null = null;
  for (const { timestamp } of messages) {
    if (
      latest === null ||
      timestamp.millis() > latest.millis() ||
      (timestamp.millis() === latest.millis() &&
        timestamp.counter() > latest.counter())
    ) {
      latest = timestamp;
    }
  }

  const clock = getClock();
  const savedMillis = clock.timestamp.millis();
  const savedCounter = clock.timestamp.counter();
  try {
    db.transaction(
      () => {
        if (latest !== null) {
          Timestamp.recv(latest);
        }
        applyInTransaction();
      },
      { immediate: true },
    );
  } catch (e) {
    clock.timestamp.setMillis(savedMillis);
    clock.timestamp.setCounter(savedCounter);
    throw e;
  }
}

export async function receiveMessages(messages: Message[]): Promise<Message[]> {
  try {
    return await runMutator(() => applyMessages(messages, true));
  } catch (e) {
    if (e instanceof Timestamp.ClockDriftError) {
      throw new SyncError('clock-drift');
    }
    throw e;
  }
}

async function errorHandler(e: Error) {
  captureException(e);

  if (e instanceof SyncError) {
    if (e.reason === 'invalid-schema') {
      // We know this message came from a local modification, and it
      // couldn't apply, which doesn't make any sense. Must be a bug
      // in the code. Send a specific error type for it for a custom
      // message.
      app.events.emit('sync', {
        type: 'error',
        subtype: 'apply-failure',
        meta: e.meta,
      });
    } else {
      app.events.emit('sync', { type: 'error', meta: e.meta });
    }
  } else if (e instanceof Timestamp.ClockDriftError) {
    app.events.emit('sync', {
      type: 'error',
      subtype: 'clock-drift',
      meta: { message: e.message },
    });
  }
}

async function _sendMessages(messages: Message[]): Promise<void> {
  try {
    await applyMessages(messages);
  } catch (e) {
    void errorHandler(e);
    throw e;
  }

  await scheduleFullSync();
}

let IS_BATCHING = false;
let _BATCHED: Message[] = [];
export async function batchMessages(func: () => Promise<void>): Promise<void> {
  if (IS_BATCHING) {
    await func();
    return;
  }

  IS_BATCHING = true;
  let batched: Message[] = [];

  try {
    await func();
  } catch (e) {
    void errorHandler(e);
    throw e;
  } finally {
    IS_BATCHING = false;
    batched = _BATCHED;
    _BATCHED = [];
  }

  if (batched.length > 0) {
    await _sendMessages(batched);
  }
}

export async function sendMessages(messages: Message[]) {
  if (IS_BATCHING) {
    _BATCHED = _BATCHED.concat(messages);
  } else {
    return _sendMessages(messages);
  }
}

