// @ts-strict-ignore
// Temporary exploration harness: compares the live spreadsheet against a
// from-scratch rebuild after each reorganisation step.
import * as db from '#server/db';
import { runHandler } from '#server/mutators';
import * as sheet from '#server/sheet';
import * as monthUtils from '#shared/months';

import { app } from './app';
import { createAllBudgets } from './base';

const handlers = app.handlers;

async function snapshot(type) {
  await sheet.waitOnSpreadsheet();
  const months = [...sheet.get().meta().createdMonths].sort();
  const out = {};
  for (const month of months) {
    const values = await handlers[
      type === 'tracking' ? 'tracking-budget-month' : 'envelope-budget-month'
    ]({ month });
    for (const { name, value } of values) {
      out[name] = value;
    }
  }
  return out;
}

async function rebuild(type) {
  sheet.unloadSpreadsheet();
  await sheet.loadSpreadsheet(db);
  sheet.get().meta().budgetType = type;
  await createAllBudgets();
  await sheet.waitOnSpreadsheet();
}

async function names() {
  const cats = await db.all<{ id: string; name: string }>(
    'SELECT id, name FROM categories',
  );
  const groups = await db.all<{ id: string; name: string }>(
    'SELECT id, name FROM category_groups',
  );
  const map = new Map<string, string>();
  [...cats, ...groups].forEach(r => map.set(r.id, r.name));
  return map;
}

async function check(label, type) {
  const live = await snapshot(type);
  // Invariant on the live sheet (envelope only)
  await rebuild(type);
  const fresh = await snapshot(type);
  const map = await names();
  const pretty = n => {
    for (const [id, name] of map) {
      n = n.replace(id, `<${name}>`);
    }
    return n;
  };
  const diffs = [];
  for (const key of new Set([...Object.keys(live), ...Object.keys(fresh)])) {
    const a = live[key] ?? 0;
    const b = fresh[key] ?? 0;
    if ((a || 0) !== (b || 0)) {
      diffs.push(`${pretty(key)}: live=${a} fresh=${b}`);
    }
  }
  console.error(
    `[${type}] ${label}: ${diffs.length} diffs` +
      (diffs.length ? '\n  ' + diffs.slice(0, 40).join('\n  ') : ''),
  );
  return diffs;
}

async function invariant(label) {
  await sheet.waitOnSpreadsheet();
  const months = [...sheet.get().meta().createdMonths].sort();
  const problems = [];
  for (const month of months) {
    const s = monthUtils.sheetForMonth(month);
    const v = n => sheet.getCellValue(s, n) || 0;
    const cats = await db.all<{ id: string; is_income: number }>(
      'SELECT id, is_income FROM categories WHERE tombstone = 0',
    );
    const leftover = cats
      .filter(c => !c.is_income)
      .reduce((t, c) => t + (v(`leftover-${c.id}`) as number), 0);
    const { end } = monthUtils.bounds(month);
    const row = await db.first<{ a: number }>(
      `SELECT SUM(t.amount) as a FROM v_transactions_internal_alive t
       LEFT JOIN accounts a ON a.id = t.account
       WHERE t.date <= ${end} AND t.category IS NOT NULL AND a.offbudget = 0`,
    );
    const cash = row.a || 0;
    const total =
      (v('to-budget') as number) + (v('buffered') as number) + leftover;
    // overspending not carried reduces next month's to-budget, so compare
    // using the definition: T + B + sum(leftover) == cash
    if (total !== cash) {
      problems.push(
        `${month}: to-budget ${v('to-budget')} + buffered ${v('buffered')} + leftover ${leftover} = ${total} != cash ${cash}`,
      );
    }
    if (v('total-leftover') !== leftover) {
      problems.push(
        `${month}: total-leftover ${v('total-leftover')} != sum ${leftover}`,
      );
    }
  }
  console.error(
    `INVARIANT ${label}: ${problems.length} problems` +
      (problems.length ? '\n  ' + problems.slice(0, 10).join('\n  ') : ''),
  );
}

