// Temporary exploration harness: compares the live spreadsheet against a
// from-scratch rebuild after each reorganisation step. Not to be committed.
import * as db from '#server/db';
import { runHandler } from '#server/mutators';
import * as sheet from '#server/sheet';
import * as monthUtils from '#shared/months';

import { app } from './app';
import { createAllBudgets } from './base';

type BudgetType = 'envelope' | 'tracking';
type Snapshot = Record<string, unknown>;

const handlers = app.handlers;

async function snapshot(type: BudgetType): Promise<Snapshot> {
  await sheet.waitOnSpreadsheet();
  const months = [...sheet.get().meta().createdMonths].sort();
  const out: Snapshot = {};
  for (const month of months) {
    const values = await handlers[
      type === 'tracking' ? 'tracking-budget-month' : 'envelope-budget-month'
    ]({ month });
    for (const { name, value } of values) {
      out[name] = value;
    }
  }
  return out;
}

async function rebuild(type: BudgetType) {
  sheet.unloadSpreadsheet();
  await sheet.loadSpreadsheet(db);
  sheet.get().meta().budgetType = type;
  await createAllBudgets();
  await sheet.waitOnSpreadsheet();
}

async function names() {
  const cats = await db.all<{ id: string; name: string }>(
    'SELECT id, name FROM categories',
  );
  const groups = await db.all<{ id: string; name: string }>(
    'SELECT id, name FROM category_groups',
  );
  const map = new Map<string, string>();
  [...cats, ...groups].forEach(r => map.set(r.id, r.name));
  return map;
}

async function check(label: string, type: BudgetType) {
  const live = await snapshot(type);
  await rebuild(type);
  const fresh = await snapshot(type);
  const map = await names();
  const pretty = (n: string) => {
    for (const [id, name] of map) {
      n = n.replace(id, `<${name}>`);
    }
    return n;
  };
  const diffs: string[] = [];
  for (const key of new Set([...Object.keys(live), ...Object.keys(fresh)])) {
    const a = live[key] ?? 0;
    const b = fresh[key] ?? 0;
    if ((a || 0) !== (b || 0)) {
      diffs.push(`${pretty(key)}: live=${String(a)} fresh=${String(b)}`);
    }
  }
  console.error(
    `[${type}] ${label}: ${diffs.length} diffs` +
      (diffs.length ? '\n  ' + diffs.slice(0, 40).join('\n  ') : ''),
  );
  return diffs;
}

async function invariant(label: string) {
  await sheet.waitOnSpreadsheet();
  const months = [...sheet.get().meta().createdMonths].sort();
  const problems: string[] = [];
  for (const month of months) {
    const s = monthUtils.sheetForMonth(month);
    const v = (n: string) => Number(sheet.getCellValue(s, n) || 0);
    const cats = await db.all<{ id: string; is_income: number }>(
      'SELECT id, is_income FROM categories WHERE tombstone = 0',
    );
    const leftover = cats
      .filter(c => !c.is_income)
      .reduce((t, c) => t + v(`leftover-${c.id}`), 0);
    const { end } = monthUtils.bounds(month);
    const row = await db.first<{ a: number }>(
      `SELECT SUM(t.amount) as a FROM v_transactions_internal_alive t
       LEFT JOIN accounts a ON a.id = t.account
       WHERE t.date <= ${end} AND t.category IS NOT NULL AND a.offbudget = 0`,
    );
    const cash = row?.a || 0;
    const total = v('to-budget') + v('buffered') + leftover;
    if (total !== cash) {
      problems.push(
        `${month}: to-budget ${v('to-budget')} + buffered ${v('buffered')} + leftover ${leftover} = ${total} != cash ${cash}`,
      );
    }
    if (v('total-leftover') !== leftover) {
      problems.push(
        `${month}: total-leftover ${v('total-leftover')} != sum ${leftover}`,
      );
    }
  }
  console.error(
    `INVARIANT ${label}: ${problems.length} problems` +
      (problems.length ? '\n  ' + problems.slice(0, 10).join('\n  ') : ''),
  );
}

const MONTHS = ['2016-10', '2016-11', '2016-12', '2017-01'];

async function seed(type: BudgetType) {
  db.runQuery("INSERT INTO preferences (id, value) VALUES ('budgetType', ?)", [
    type,
  ]);
  await sheet.loadSpreadsheet(db);
  sheet.get().meta().budgetType = type;

  await db.insertCategoryGroup({ id: 'income', name: 'Income', is_income: 1 });
  await db.insertCategory({
    id: 'salary',
    name: 'Salary',
    cat_group: 'income',
    is_income: 1,
  });
  await db.insertCategory({
    id: 'sales',
    name: 'Sales',
    cat_group: 'income',
    is_income: 1,
  });
  await db.insertCategoryGroup({ id: 'home', name: 'Home' });
  await db.insertCategoryGroup({ id: 'biz', name: 'Business' });
  await db.insertCategoryGroup({ id: 'misc', name: 'Misc' });
  for (const [id, group] of [
    ['food', 'home'],
    ['rent', 'home'],
    ['fun', 'home'],
    ['stock', 'biz'],
    ['tools', 'biz'],
    ['fees', 'misc'],
    ['gifts', 'misc'],
  ]) {
    await db.insertCategory({ id, name: id, cat_group: group });
  }
  await db.insertAccount({ id: 'checking', name: 'Checking' });
  await db.insertAccount({ id: 'bizacct', name: 'Biz' });
  await db.insertAccount({ id: 'invest', name: 'Invest', offbudget: 1 });

  const tx = (
    date: string,
    amount: number,
    category: string,
    account = 'checking',
  ) => db.insertTransaction({ date, amount, category, account });

  for (const m of MONTHS) {
    await tx(`${m}-01`, 500000, 'salary');
    await tx(`${m}-02`, 200000, 'sales', 'bizacct');
    await tx(`${m}-03`, -40000, 'food');
    await tx(`${m}-04`, -100000, 'rent');
    await tx(`${m}-05`, -7000, 'fun');
    await tx(`${m}-06`, -60000, 'stock', 'bizacct');
    await tx(`${m}-07`, -9000, 'tools', 'bizacct');
    await tx(`${m}-08`, -1500, 'fees');
    await tx(`${m}-09`, -2500, 'gifts', 'invest');
  }
  await createAllBudgets();

  const set = (month: string, category: string, amount: number) =>
    runHandler(handlers['budget/budget-amount'], { month, category, amount });
  for (const m of MONTHS) {
    await set(m, 'food', 35000); // overspent every month
    await set(m, 'rent', 100000);
    await set(m, 'fun', 10000);
    await set(m, 'stock', 50000); // overspent
    await set(m, 'tools', 12000);
    await set(m, 'fees', 1000);
    await set(m, 'gifts', 3000);
  }
  await sheet.waitOnSpreadsheet();
}

describe.each(['envelope', 'tracking'] as const)('repro %s', type => {
  beforeEach(async () => {
    await global.emptyDatabase()();
    await seed(type);
  });

  it('baseline', async () => {
    if (type === 'envelope') await invariant('baseline');
    await check('baseline', type);
  });

  it('rollover overspending + delete with transfer', async () => {
    await runHandler(handlers['budget/set-carryover'], {
      startMonth: '2016-10',
      category: 'stock',
      flag: true,
    });
    await check('carryover on stock', type);
    await runHandler(handlers['category-delete'], {
      id: 'stock',
      transferId: 'tools',
    });
    if (type === 'envelope') await invariant('delete stock->tools');
    await check('delete stock->tools', type);
  });

  it('delete with transfer then edit transactions', async () => {
    await runHandler(handlers['category-delete'], {
      id: 'fun',
      transferId: 'food',
    });
    if (type === 'envelope') await invariant('delete fun->food');
    await check('delete fun->food', type);

    const t = await db.first<{ id: string }>(
      "SELECT id FROM transactions WHERE category = 'fun' LIMIT 1",
    );
    await db.updateTransaction({ id: t?.id, amount: -99900 });
    if (type === 'envelope') await invariant('edit merged tx');
    await check('edit merged tx', type);

    await db.updateAccount({ id: 'checking', offbudget: 1 });
    await check('checking -> offbudget', type);
    await db.updateAccount({ id: 'checking', offbudget: 0 });
    await check('checking -> onbudget', type);
    await db.updateAccount({ id: 'invest', offbudget: 0 });
    await check('invest -> onbudget', type);
  });

  it('move category between groups', async () => {
    await runHandler(handlers['category-move'], {
      id: 'tools',
      groupId: 'home',
      targetId: null,
    });
    if (type === 'envelope') await invariant('move tools->home');
    await check('move tools->home', type);
    await runHandler(handlers['category-update'], {
      id: 'fees',
      name: 'fees',
      group: 'biz',
    } as never);
    await check('update fees group->biz', type);
  });

  it('delete group with transfer', async () => {
    await runHandler(handlers['category-delete'], {
      id: 'fees',
      transferId: 'food',
    });
    await check('delete fees->food', type);
    await runHandler(handlers['category-group-delete'], {
      id: 'misc',
      transferId: 'tools',
    });
    if (type === 'envelope') await invariant('delete group misc->tools');
    await check('delete group misc->tools', type);
    const rows = await db.all('SELECT * FROM category_mapping');
    console.error(JSON.stringify(rows));
    const budgets = await db.all(
      `SELECT category, month, amount FROM ${type === 'tracking' ? 'reflect_budgets' : 'zero_budgets'} WHERE month = 201611`,
    );
    console.error(JSON.stringify(budgets));
  });

  it('reallocate funds', async () => {
    await runHandler(handlers['budget/transfer-category'], {
      month: '2016-11',
      amount: 2000,
      from: 'fun',
      to: 'food',
      currencyCode: 'USD',
    });
    await runHandler(handlers['budget/cover-overspending'], {
      month: '2016-11',
      to: 'stock',
      from: 'tools',
      currencyCode: 'USD',
    });
    await runHandler(handlers['budget/cover-overspending'], {
      month: '2016-12',
      to: 'stock',
      from: 'to-budget',
      currencyCode: 'USD',
    });
    await runHandler(handlers['budget/hold-for-next-month'], {
      month: '2016-12',
      amount: 5000,
    });
    await runHandler(handlers['budget/transfer-available'], {
      month: '2017-01',
      amount: 5000,
      category: 'gifts',
    });
    await runHandler(handlers['budget/transfer-category'], {
      month: '2017-01',
      amount: 2000,
      from: 'gifts',
      to: 'to-budget',
      currencyCode: 'USD',
    });
    if (type === 'envelope') await invariant('reallocate');
    await check('reallocate', type);
  });

  it('hide / unhide', async () => {
    await runHandler(handlers['category-update'], {
      id: 'fun',
      name: 'fun',
      hidden: true,
      group: 'home',
    } as never);
    await check('hide fun', type);
    await runHandler(handlers['category-move'], {
      id: 'fun',
      groupId: 'biz',
      targetId: null,
    });
    await check('move hidden fun -> biz', type);
    await runHandler(handlers['category-group-update'], {
      id: 'misc',
      name: 'Misc',
      hidden: true,
      is_income: false,
    } as never);
    await check('hide misc', type);
    await runHandler(handlers['category-create'], {
      name: 'newcat',
      groupId: 'misc',
    });
    await check('create in hidden group', type);
    await runHandler(handlers['category-create'], {
      name: 'newhidden',
      groupId: 'home',
      hidden: true,
    });
    await check('create hidden cat', type);
    await runHandler(handlers['category-group-create'], {
      name: 'HiddenGroup',
      hidden: true,
    });
    await check('create hidden group', type);
    await runHandler(handlers['category-group-update'], {
      id: 'income',
      name: 'Income',
      hidden: true,
      is_income: true,
    } as never);
    await runHandler(handlers['category-group-update'], {
      id: 'income',
      name: 'Income',
      hidden: false,
      is_income: true,
    } as never);
    await check('hide+unhide income group', type);
  });
});

