describe.each(['envelope', 'tracking'] as const)('repro2 %s', type => {
  beforeEach(async () => {
    await global.emptyDatabase()();
    await seed(type);
  });

  it('undo flows', async () => {
    const { undo, clearUndo } = await import('#server/undo');
    clearUndo();
    const before = await snapshot(type);
    await runHandler(
      handlers['category-delete'],
      { id: 'stock', transferId: 'tools' },
      { undoTag: 'a' },
    );
    await check('delete stock->tools', type);
    await undo();
    if (type === 'envelope') await invariant('undo delete');
    const after = await snapshot(type);
    const d = Object.keys(before).filter(k => before[k] !== after[k]);
    console.error(`undo delete vs before: ${d.length} diffs ${d.slice(0, 10).map(k => `${k}: ${before[k]} -> ${after[k]}`).join('; ')}`);
    await check('undo delete', type);

    await runHandler(
      handlers['category-group-delete'],
      { id: 'misc', transferId: 'tools' },
      { undoTag: 'b' },
    );
    await undo();
    const after2 = await snapshot(type);
    const d2 = Object.keys(before).filter(k => before[k] !== after2[k]);
    console.error(`undo group delete vs before: ${d2.length} diffs ${d2.slice(0, 10).map(k => `${k}: ${before[k]} -> ${after2[k]}`).join('; ')}`);
    await check('undo group delete', type);

    await runHandler(
      handlers['category-move'],
      { id: 'tools', groupId: 'home', targetId: null },
      { undoTag: 'c' },
    );
    await undo();
    const after3 = await snapshot(type);
    const d3 = Object.keys(before).filter(k => before[k] !== after3[k]);
    console.error(`undo move vs before: ${d3.length} diffs ${d3.slice(0, 10).map(k => `${k}: ${before[k]} -> ${after3[k]}`).join('; ')}`);
    await check('undo move', type);
  });

  it('income category delete with transfer', async () => {
    await runHandler(handlers['budget/budget-amount'], {
      month: '2016-11',
      category: 'sales',
      amount: 180000,
    });
    await runHandler(handlers['budget/budget-amount'], {
      month: '2016-11',
      category: 'salary',
      amount: 500000,
    });
    const s = monthUtils.sheetForMonth('2016-11');
    const pre = {
      inc: sheet.getCellValue(s, 'total-income'),
      binc: sheet.getCellValue(s, 'total-budget-income'),
    };
    await runHandler(handlers['category-delete'], {
      id: 'sales',
      transferId: 'salary',
    });
    await sheet.waitOnSpreadsheet();
    console.error(
      `[${type}] income merge: before ${JSON.stringify(pre)} after ${JSON.stringify({ inc: sheet.getCellValue(s, 'total-income'), binc: sheet.getCellValue(s, 'total-budget-income'), salaryBudget: sheet.getCellValue(s, 'budget-salary') })}`,
    );
    if (type === 'envelope') await invariant('income merge');
    await check('income merge', type);
  });

  it('new category, then older history added', async () => {
    const id = await runHandler(handlers['category-create'], {
      name: 'brandnew',
      groupId: 'biz',
    });
    await runHandler(handlers['budget/budget-amount'], {
      month: '2016-11',
      category: id,
      amount: 4000,
    });
    await db.insertTransaction({
      date: '2016-11-20',
      amount: -9000,
      category: id,
      account: 'bizacct',
    });
    if (type === 'envelope') await invariant('new category');
    await check('new category', type);
    await runHandler(handlers['category-delete'], {
      id: 'fun',
      transferId: id,
    });
    await db.insertTransaction({
      date: '2016-03-20',
      amount: -1000,
      category: 'fun',
      account: 'checking',
    });
    await createAllBudgets();
    if (type === 'envelope') await invariant('older history');
    await check('older history', type);
  });

  it('carryover + merge + reallocation', async () => {
    await runHandler(handlers['budget/set-carryover'], {
      startMonth: '2016-10',
      category: 'food',
      flag: true,
    });
    await runHandler(handlers['category-delete'], {
      id: 'food',
      transferId: 'fun',
    });
    await runHandler(handlers['budget/cover-overspending'], {
      month: '2016-12',
      to: 'fun',
      from: 'tools',
      currencyCode: 'USD',
    });
    await runHandler(handlers['budget/transfer-category'], {
      month: '2016-12',
      amount: 500,
      from: 'rent',
      to: 'fun',
      currencyCode: 'USD',
    });
    if (type === 'envelope') await invariant('carry merge realloc');
    await check('carry merge realloc', type);
  });
});
