function rng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

async function fuzz(type: BudgetType, seedNum: number, steps: number) {
  const { undo, clearUndo } = await import('#server/undo');
  clearUndo();
  const rand = rng(seedNum);
  const pick = <T,>(arr: T[]): T => arr[Math.floor(rand() * arr.length)];
  const log: string[] = [];
  let tag = 0;
  const run = async (name: string, args: unknown) => {
    log.push(`${name} ${JSON.stringify(args)}`);
    try {
      // oxlint-disable-next-line typescript/no-explicit-any
      return await runHandler((handlers as any)[name], args as never, {
        undoTag: `t${tag++}`,
      });
    } catch (e) {
      log.push(`  -> threw ${(e as Error).message}`);
    }
  };
  const months = [...MONTHS, '2017-02'];
  type Cat = { id: string; cat_group: string; is_income: number; hidden: number };
  const cats = () =>
    db.all<Cat>('SELECT * FROM categories WHERE tombstone = 0');
  const groups = () =>
    db.all<{ id: string; is_income: number; hidden: number; name: string }>(
      'SELECT * FROM category_groups WHERE tombstone = 0',
    );

  for (let i = 0; i < steps; i++) {
    const all = await cats();
    const exp = all.filter(c => !c.is_income);
    const gs = (await groups()).filter(g => !g.is_income);
    const r = Math.floor(rand() * 19);
    const month = pick(months);
    if (exp.length < 2 || gs.length < 2) break;
    switch (r) {
      case 0:
        await run('budget/budget-amount', {
          month,
          category: pick(exp).id,
          amount: Math.floor(rand() * 50000),
        });
        break;
      case 1: {
        const from = pick(exp).id;
        const to = pick(exp.filter(c => c.id !== from)).id;
        await run('budget/transfer-category', {
          month,
          amount: Math.floor(rand() * 9000),
          from,
          to,
          currencyCode: 'USD',
        });
        break;
      }
      case 2: {
        const to = pick(exp).id;
        const from = rand() < 0.3 ? 'to-budget' : pick(exp.filter(c => c.id !== to)).id;
        if (type === 'envelope')
          await run('budget/cover-overspending', { month, to, from, currencyCode: 'USD' });
        break;
      }
      case 3:
        if (type === 'envelope')
          await run('budget/hold-for-next-month', { month, amount: Math.floor(rand() * 9000) });
        break;
      case 4:
        await run('budget/set-carryover', {
          startMonth: month,
          category: pick(exp).id,
          flag: rand() < 0.6,
        });
        break;
      case 5:
        await run('category-create', {
          name: `c${seedNum}-${i}`,
          groupId: pick(gs).id,
          hidden: rand() < 0.2,
        });
        break;
      case 6:
        await run('category-group-create', { name: `g${seedNum}-${i}` });
        break;
      case 7:
      case 8:
        await run('category-move', {
          id: pick(exp).id,
          groupId: pick(gs).id,
          targetId: null,
        });
        break;
      case 9: {
        const c = pick(exp);
        await run('category-update', {
          id: c.id,
          hidden: !c.hidden,
        });
        break;
      }
      case 10: {
        const g = pick(gs);
        await run('category-group-update', {
          id: g.id,
          name: g.name,
          hidden: !g.hidden,
          is_income: false,
        });
        break;
      }
      case 11:
      case 12: {
        const c = pick(exp);
        const must = await handlers['must-category-transfer']({ id: c.id });
        await run('category-delete', {
          id: c.id,
          transferId: must || rand() < 0.5 ? pick(exp.filter(x => x.id !== c.id)).id : undefined,
        });
        break;
      }
      case 13: {
        const g = pick(gs);
        const outside = exp.filter(c => c.cat_group !== g.id);
        if (outside.length === 0) break;
        await run('category-group-delete', { id: g.id, transferId: pick(outside).id });
        break;
      }
      case 14:
        log.push('insert tx');
        await db.insertTransaction({
          date: `${month}-15`,
          amount: -Math.floor(rand() * 20000),
          category: pick(exp).id,
          account: pick(['checking', 'bizacct', 'invest']),
        });
        break;
      case 15: {
        const t = pick(
          await db.all<{ id: string }>('SELECT id FROM transactions WHERE tombstone = 0'),
        );
        log.push(`update tx ${t.id}`);
        if (rand() < 0.5) {
          await db.updateTransaction({ id: t.id, amount: -Math.floor(rand() * 30000) });
        } else if (rand() < 0.5) {
          await db.updateTransaction({ id: t.id, category: pick(exp).id });
        } else {
          await db.deleteTransaction({ id: t.id });
        }
        break;
      }
      case 16: {
        const id = pick(['checking', 'bizacct', 'invest']);
        const a = await db.first<{ offbudget: number }>('SELECT offbudget FROM accounts WHERE id = ?', [id]);
        log.push(`toggle offbudget ${id}`);
        await db.updateAccount({ id, offbudget: a?.offbudget ? 0 : 1 });
        break;
      }
      case 17:
        log.push('undo');
        await undo();
        break;
      case 18:
        await run(pick(['budget/copy-previous-month', 'budget/set-3month-avg']), { month });
        break;
    }
    await sheet.waitOnSpreadsheet();
  }
  return log;
}

describe.each(['envelope', 'tracking'] as const)('fuzz %s', type => {
  beforeEach(async () => {
    await global.emptyDatabase()();
    await seed(type);
  });

  const N = Number(process.env.FUZZ_N || 40);
  const STEPS = Number(process.env.FUZZ_STEPS || 5);
  const START = Number(process.env.FUZZ_START || 1);
  it.each(Array.from({ length: N }, (_, i) => i + START))('seed %i', async s => {
    const log = await fuzz(type, s, STEPS);
    const live = await snapshot(type);
    await rebuild(type);
    const fresh = await snapshot(type);
    const keys = [...new Set([...Object.keys(live), ...Object.keys(fresh)])].filter(
      k => (live[k] || 0) !== (fresh[k] || 0),
    );
    if (keys.length) {
      console.error(
        `FUZZ ${type} seed ${s}: ${keys.length} diffs\n  ${log.join('\n  ')}\n  -- ${keys
          .slice(0, 6)
          .map(k => `${k}: live=${String(live[k])} fresh=${String(fresh[k])}`)
          .join('\n  -- ')}`,
      );
    }
  });
});
