// Replays everything a fuzz run changed onto a copy of the starting state as
// one batch of messages, the way a device that was offline receives it.
const SYNCED_TABLES = [
  'category_groups',
  'categories',
  'category_mapping',
  'zero_budgets',
  'reflect_budgets',
  'zero_budget_months',
  'accounts',
  'transactions',
];

function dumpTables() {
  const out = new Map<string, Map<string, Record<string, unknown>>>();
  for (const table of SYNCED_TABLES) {
    const rows = db.runQuery<Record<string, unknown>>(
      `SELECT * FROM ${table}`,
      [],
      true,
    );
    out.set(table, new Map(rows.map(r => [String(r.id), r])));
  }
  return out;
}

describe.each(['envelope', 'tracking'] as const)('syncfuzz %s', type => {
  beforeEach(async () => {
    await global.emptyDatabase()();
    await seed(type);
  });

  const N = Number(process.env.FUZZ_N || 40);
  const STEPS = Number(process.env.FUZZ_STEPS || 5);
  const START = Number(process.env.FUZZ_START || 1);
  it.each(Array.from({ length: N }, (_, i) => i + START))('seed %i', async s => {
    const sqlite = await import('#platform/server/sqlite');
    const { sendMessages } = await import('#server/sync');
    const { Timestamp } = await import('@actual-app/crdt');
    // oxlint-disable-next-line typescript/no-explicit-any
    const image = (db.getDatabase() as any).serialize();
    const before = dumpTables();
    const log = await fuzz(type, s, STEPS);
    const after = dumpTables();

    // Back to the starting state, with a sheet built from it
    db.setDatabase(sqlite.openDatabase(image));
    await rebuild(type);

    const messages = [];
    for (const table of SYNCED_TABLES) {
      for (const [id, row] of after.get(table) ?? []) {
        const old = before.get(table)?.get(id);
        for (const column of Object.keys(row)) {
          if (column === 'id') continue;
          if (!old ? row[column] != null : old[column] !== row[column]) {
            messages.push({
              dataset: table,
              row: id,
              column,
              value: row[column] as string | number | null,
              timestamp: Timestamp.send(),
            });
          }
        }
      }
    }
    // oxlint-disable-next-line typescript/no-explicit-any
    await sendMessages(messages as any);

    const live = await snapshot(type);
    await rebuild(type);
    const fresh = await snapshot(type);
    const keys = [...new Set([...Object.keys(live), ...Object.keys(fresh)])].filter(
      k => (live[k] || 0) !== (fresh[k] || 0),
    );
    if (keys.length) {
      console.error(
        `SYNCFUZZ ${type} seed ${s}: ${keys.length} diffs\n  ${log.join('\n  ')}\n  -- ${keys
          .slice(0, 6)
          .map(k => `${k}: live=${String(live[k])} fresh=${String(fresh[k])}`)
          .join('\n  -- ')}`,
      );
    }
  });
});
