import { app } from './app';
import { createAllBudgets } from './base';

const handlers = app.handlers;

type Txn = {
  id: string;
  month: string;
  amount: number;
  category: string;
  account: string;
};

class Ledger {
  months: string[] = [];
  expense = new Set<string>();
  income = new Set<string>();
  onBudget = new Map<string, boolean>();
  txns: Txn[] = [];
  budget = new Map<string, number>(); // `${month}|${cat}`
  rollover = new Map<string, boolean>();
  autoHold = new Map<string, boolean>();
  held = new Map<string, number>();

  b(month: string, cat: string) {
    return this.budget.get(`${month}|${cat}`) || 0;
  }
  setB(month: string, cat: string, amount: number) {
    this.budget.set(`${month}|${cat}`, amount);
  }
  activity(month: string, cat: string) {
    return this.txns
      .filter(
        t =>
          t.month === month &&
          t.category === cat &&
          this.onBudget.get(t.account),
      )
      .reduce((s, t) => s + t.amount, 0);
  }
  cashThrough(month: string) {
    return this.txns
      .filter(t => t.month <= month && this.onBudget.get(t.account))
      .reduce((s, t) => s + t.amount, 0);
  }

  compute() {
    const out = new Map<
      string,
      {
        toBudget: number;
        held: number;
        budgeted: number;
        spent: number;
        income: number;
        balances: Map<string, number>;
      }
    >();
    let prevToBudget = 0;
    let prevHeld = 0;
    let prevOverspent = 0;
    const carried = new Map<string, number>();
    for (const month of this.months) {
      let budgeted = 0;
      let spent = 0;
      let overspent = 0;
      const balances = new Map<string, number>();
      for (const cat of this.expense) {
        const bud = this.b(month, cat);
        const act = this.activity(month, cat);
        const bal = (carried.get(cat) || 0) + bud + act;
        budgeted += bud;
        spent += act;
        balances.set(cat, bal);
        if (bal < 0 && !this.rollover.get(`${month}|${cat}`)) {
          // Overspending comes out of next month's To Budget and the
          // category starts again from zero
          overspent += bal;
          carried.set(cat, 0);
        } else {
          carried.set(cat, bal);
        }
      }
      let income = 0;
      let autoHeld = 0;
      for (const cat of this.income) {
        const act = this.activity(month, cat);
        income += act;
        if (this.autoHold.get(`${month}|${cat}`)) {
          autoHeld += act;
        }
      }
      const manual = this.held.get(month) || 0;
      const held = manual !== 0 ? manual : autoHeld;
      const toBudget =
        income + prevToBudget + prevHeld + prevOverspent - budgeted - held;
      out.set(month, { toBudget, held, budgeted, spent, income, balances });
      prevToBudget = toBudget;
      prevHeld = held;
      prevOverspent = overspent;
    }
    return out;
  }
}

function rng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

const TX_MONTHS = ['2016-10', '2016-11', '2016-12', '2017-01'];

async function seedBoth(ledger: Ledger) {
  await sheet.loadSpreadsheet(db);

  await db.insertCategoryGroup({ id: 'income', name: 'Income', is_income: 1 });
  for (const id of ['salary', 'sales']) {
    await db.insertCategory({
      id,
      name: id,
      cat_group: 'income',
      is_income: 1,
    });
    ledger.income.add(id);
  }
  await db.insertCategoryGroup({ id: 'home', name: 'Home' });
  await db.insertCategoryGroup({ id: 'biz', name: 'Business' });
  await db.insertCategoryGroup({ id: 'misc', name: 'Misc' });
  for (const [id, group] of [
    ['food', 'home'],
    ['rent', 'home'],
    ['fun', 'home'],
    ['stock', 'biz'],
    ['tools', 'biz'],
    ['fees', 'misc'],
    ['gifts', 'misc'],
  ]) {
    await db.insertCategory({ id, name: id, cat_group: group });
    ledger.expense.add(id);
  }
  for (const [id, off] of [
    ['checking', 0],
    ['bizacct', 0],
    ['invest', 1],
  ] as const) {
    await db.insertAccount({ id, name: id, offbudget: off });
    ledger.onBudget.set(id, !off);
  }

  let n = 0;
  const tx = async (
    month: string,
    amount: number,
    category: string,
    account = 'checking',
  ) => {
    const id = `t${n++}`;
    await db.insertTransaction({
      id,
      date: `${month}-1${n % 9}`,
      amount,
      category,
      account,
    });
    ledger.txns.push({ id, month, amount, category, account });
  };
  for (const m of TX_MONTHS) {
    await tx(m, 500000, 'salary');
    await tx(m, 200000, 'sales', 'bizacct');
    await tx(m, -40000, 'food');
    await tx(m, -100000, 'rent');
    await tx(m, -7000, 'fun');
    await tx(m, -60000, 'stock', 'bizacct');
    await tx(m, -9000, 'tools', 'bizacct');
    await tx(m, -1500, 'fees');
    await tx(m, -2500, 'gifts', 'invest');
  }
  await createAllBudgets();
  ledger.months = [...sheet.get().meta().createdMonths].sort();

  for (const m of TX_MONTHS) {
    for (const [cat, amount] of [
      ['food', 35000],
      ['rent', 100000],
      ['fun', 10000],
      ['stock', 50000],
      ['tools', 12000],
      ['fees', 1000],
      ['gifts', 3000],
    ] as const) {
      await runHandler(handlers['budget/budget-amount'], {
        month: m,
        category: cat,
        amount,
      });
      ledger.setB(m, cat, amount);
    }
  }
  await sheet.waitOnSpreadsheet();
}

// Compares every month's figures in the app with the ledger and with the
// cash actually in the on-budget accounts.
async function compare(ledger: Ledger): Promise<string[]> {
  await sheet.waitOnSpreadsheet();
  const expected = ledger.compute();
  const problems: string[] = [];
  for (const month of ledger.months) {
    const s = monthUtils.sheetForMonth(month);
    const v = (n: string) => Number(sheet.getCellValue(s, n) || 0);
    const e = expected.get(month);
    if (!e) continue;
    const check = (label: string, actual: number, want: number) => {
      if (actual !== want) {
        problems.push(`${month} ${label}: app=${actual} should be=${want}`);
      }
    };
    check('to-budget', v('to-budget'), e.toBudget);
    check('held for next month', v('buffered-selected'), e.held);
    check('total budgeted', -v('total-budgeted'), e.budgeted);
    check('total spent', v('total-spent'), e.spent);
    check('total income', v('total-income'), e.income);
    let balanceSum = 0;
    for (const [cat, bal] of e.balances) {
      check(`balance ${cat}`, v(`leftover-${cat}`), bal);
      check(`budgeted ${cat}`, v(`budget-${cat}`), ledger.b(month, cat));
      check(`spent ${cat}`, v(`sum-amount-${cat}`), ledger.activity(month, cat));
      balanceSum += v(`leftover-${cat}`);
    }
    check('total balance', v('total-leftover'), balanceSum);

    // Real money: what is in the on-budget accounts, from the raw rows
    const { end } = monthUtils.bounds(month);
    const row = await db.first<{ a: number }>(
      `SELECT SUM(t.amount) AS a FROM transactions t
         JOIN accounts a ON a.id = t.acct
        WHERE t.tombstone = 0 AND a.offbudget = 0 AND t.date <= ${end}`,
    );
    const cash = row?.a || 0;
    check('ledger cash vs accounts', ledger.cashThrough(month), cash);
    check(
      'to-budget + held + balances vs cash in accounts',
      v('to-budget') + v('buffered-selected') + balanceSum,
      cash,
    );
  }
  return problems;
}

async function scenario(seedNum: number, steps: number) {
  const ledger = new Ledger();
  await seedBoth(ledger);
  const rand = rng(seedNum);
  const pick = <T,>(arr: T[]): T => arr[Math.floor(rand() * arr.length)];
  const log: string[] = [];
  const months = [...TX_MONTHS, '2017-02', '2017-03'];
  let n = 1000;

  const base = await compare(ledger);
  if (base.length) return { log: ['baseline'], problems: base };

  for (let i = 0; i < steps; i++) {
    const exp = [...ledger.expense];
    const inc = [...ledger.income];
    const month = pick(months);
    const figures = ledger.compute().get(month);
    if (!figures || exp.length < 3) break;
    const r = Math.floor(rand() * 14);
    switch (r) {
      case 0: {
        const cat = pick(exp);
        const amount = Math.floor(rand() * 60000);
        log.push(`budget ${month} ${cat} = ${amount}`);
        await runHandler(handlers['budget/budget-amount'], {
          month,
          category: cat,
          amount,
        });
        ledger.setB(month, cat, amount);
        break;
      }
      case 1: {
        const from = pick(exp);
        const to = pick(exp.filter(c => c !== from));
        const amount = 1 + Math.floor(rand() * 9000);
        log.push(`transfer ${month} ${amount} ${from} -> ${to}`);
        await runHandler(handlers['budget/transfer-category'], {
          month,
          amount,
          from,
          to,
          currencyCode: 'USD',
        });
        ledger.setB(month, from, ledger.b(month, from) - amount);
        ledger.setB(month, to, ledger.b(month, to) + amount);
        break;
      }
      case 2: {
        const from = pick(exp);
        const amount = 1 + Math.floor(rand() * 9000);
        log.push(`transfer ${month} ${amount} ${from} -> to-budget`);
        await runHandler(handlers['budget/transfer-category'], {
          month,
          amount,
          from,
          to: 'to-budget',
          currencyCode: 'USD',
        });
        ledger.setB(month, from, ledger.b(month, from) - amount);
        break;
      }
      case 3: {
        const to = pick(exp);
        const from = pick(exp.filter(c => c !== to));
        log.push(`cover ${month} ${to} from ${from}`);
        await runHandler(handlers['budget/cover-overspending'], {
          month,
          to,
          from,
          currencyCode: 'USD',
        });
        const need = -(figures.balances.get(to) || 0);
        const have = figures.balances.get(from) || 0;
        if (need > 0 && have > 0) {
          const c = Math.min(need, have);
          ledger.setB(month, from, ledger.b(month, from) - c);
          ledger.setB(month, to, ledger.b(month, to) + c);
        }
        break;
      }
      case 4: {
        const to = pick(exp);
        log.push(`cover ${month} ${to} from to-budget`);
        await runHandler(handlers['budget/cover-overspending'], {
          month,
          to,
          from: 'to-budget',
          currencyCode: 'USD',
        });
        const need = -(figures.balances.get(to) || 0);
        if (need > 0 && figures.toBudget > 0) {
          const c = Math.min(need, figures.toBudget);
          ledger.setB(month, to, ledger.b(month, to) + c);
        }
        break;
      }
      case 5:
      case 6: {
        const amount = 1 + Math.floor(rand() * 400000);
        log.push(`hold ${month} ${amount} (to-budget ${figures.toBudget})`);
        await runHandler(handlers['budget/hold-for-next-month'], {
          month,
          amount,
        });
        if (figures.toBudget > 0) {
          ledger.held.set(
            month,
            (ledger.held.get(month) || 0) +
              Math.min(amount, figures.toBudget),
          );
        }
        break;
      }
      case 7: {
        log.push(`reset hold ${month}`);
        await runHandler(handlers['budget/reset-hold'], { month });
        ledger.held.set(month, 0);
        break;
      }
      case 8: {
        const cat = pick(exp);
        const amount = 1 + Math.floor(rand() * 50000);
        log.push(`transfer-available ${month} ${amount} -> ${cat}`);
        await runHandler(handlers['budget/transfer-available'], {
          month,
          amount,
          category: cat,
        });
        const c = Math.max(Math.min(amount, figures.toBudget), 0);
        ledger.setB(month, cat, ledger.b(month, cat) + c);
        break;
      }
      case 9: {
        const cat = pick(exp);
        const flag = rand() < 0.6;
        log.push(`rollover overspending ${month}+ ${cat} ${flag}`);
        await runHandler(handlers['budget/set-carryover'], {
          startMonth: month,
          category: cat,
          flag,
        });
        for (const m of ledger.months.filter(x => x >= month)) {
          ledger.rollover.set(`${m}|${cat}`, flag);
        }
        break;
      }
      case 10: {
        const cat = pick(inc);
        const flag = rand() < 0.7;
        log.push(`auto hold ${month}+ ${cat} ${flag}`);
        await runHandler(handlers['budget/set-carryover'], {
          startMonth: month,
          category: cat,
          flag,
        });
        for (const m of ledger.months.filter(x => x >= month)) {
          ledger.autoHold.set(`${m}|${cat}`, flag);
        }
        break;
      }
      case 11: {
        const cat = pick(exp);
        const to = pick(exp.filter(c => c !== cat));
        log.push(`merge ${cat} -> ${to}`);
        await runHandler(handlers['category-delete'], {
          id: cat,
          transferId: to,
        });
        for (const m of ledger.months) {
          ledger.setB(m, to, ledger.b(m, to) + ledger.b(m, cat));
        }
        ledger.txns.forEach(t => {
          if (t.category === cat) t.category = to;
        });
        ledger.expense.delete(cat);
        break;
      }
      case 12: {
        const id = `n${n++}`;
        const cat = pick(exp);
        const amount = -Math.floor(rand() * 30000);
        const account = pick(['checking', 'bizacct']);
        log.push(`spend ${month} ${amount} ${cat}`);
        await db.insertTransaction({
          id,
          date: `${month}-20`,
          amount,
          category: cat,
          account,
        });
        ledger.txns.push({ id, month, amount, category: cat, account });
        break;
      }
      case 13: {
        log.push(`cover-overbudgeted ${month}`);
        const cat = pick(exp);
        await runHandler(handlers['budget/cover-overbudgeted'], {
          month,
          category: cat,
          currencyCode: 'USD',
        });
        const bal = figures.balances.get(cat) || 0;
        if (figures.toBudget < 0 && bal > 0) {
          const c = Math.min(-figures.toBudget, bal);
          ledger.setB(month, cat, ledger.b(month, cat) - c);
        }
        break;
      }
    }
    const problems = await compare(ledger);
    if (problems.length) return { log, problems };
  }
  return { log, problems: [] as string[] };
}

describe('oracle', () => {
  beforeEach(async () => {
    await global.emptyDatabase()();
  });

  const N = Number(process.env.FUZZ_N || 60);
  const STEPS = Number(process.env.FUZZ_STEPS || 8);
  const START = Number(process.env.FUZZ_START || 1);
  it.each(Array.from({ length: N }, (_, i) => i + START))(
    'seed %i',
    async s => {
      const { log, problems } = await scenario(s, STEPS);
      if (problems.length) {
        console.error(
          `ORACLE seed ${s}: ${problems.length} problems after\n  ${log.join('\n  ')}\n  -- ${problems.slice(0, 8).join('\n  -- ')}`,
        );
      }
    },
  );
});

