// Temporary exploration harness. Not to be committed.
//
// Checks the app's budget figures against an independent ledger: a plain
// model that is told the *intent* of every action (move 20 from A to B, hold
// 50, merge A into B ...) and works out the month figures from the
// documented envelope rules, plus the real cash in the on-budget accounts
// read straight from the raw transactions table.
import * as db from '#server/db';
import { runHandler } from '#server/mutators';
import * as sheet from '#server/sheet';
import * as monthUtils from '#shared/months';

import { app } from './app';
import { createAllBudgets } from './base';

