// What each action is *meant* to do, month by month, taken from the docs
// rather than from how the app recomputes.
describe('intent', () => {
  beforeEach(async () => {
    await global.emptyDatabase()();
  });

  const cell = async (month: string, name: string) => {
    await sheet.waitOnSpreadsheet();
    return Number(
      sheet.getCellValue(monthUtils.sheetForMonth(month), name) || 0,
    );
  };
  const months = () => [...sheet.get().meta().createdMonths].sort();

  it('merge keeps To Budget and moves the balance', async () => {
    const ledger = new Ledger();
    await seedBoth(ledger);
    // food is overspent by 5,000 every month; fun has 3,000 spare
    const before: Record<string, number[]> = {};
    for (const m of months()) {
      before[m] = [
        await cell(m, 'to-budget'),
        (await cell(m, 'leftover-food')) + (await cell(m, 'leftover-fun')),
      ];
    }
    await runHandler(handlers['category-delete'], {
      id: 'food',
      transferId: 'fun',
    });
    const out: string[] = [];
    for (const m of months().slice(0, 8)) {
      out.push(
        `${m}: to-budget ${before[m][0]} -> ${await cell(m, 'to-budget')}; food+fun balance ${before[m][1]} -> ${await cell(m, 'leftover-fun')}`,
      );
    }
    console.error('MERGE INTENT\n  ' + out.join('\n  '));
  });

  it('rollover overspending and auto hold reach months added later', async () => {
    const ledger = new Ledger();
    await seedBoth(ledger);
    await runHandler(handlers['budget/set-carryover'], {
      startMonth: '2016-10',
      category: 'stock',
      flag: true,
    });
    await runHandler(handlers['budget/set-carryover'], {
      startMonth: '2016-10',
      category: 'salary',
      flag: true,
    });
    const last = months()[months().length - 1];
    // An allocation near the end extends the planning range
    await runHandler(handlers['budget/budget-amount'], {
      month: last,
      category: 'rent',
      amount: 100,
    });
    await createAllBudgets();
    const added = months().filter(m => m > last);
    const out: string[] = [];
    for (const m of [last, ...added]) {
      out.push(
        `${m}: rollover(stock)=${String(sheet.getCellValue(monthUtils.sheetForMonth(m), 'carryover-stock'))} autohold(salary)=${String(sheet.getCellValue(monthUtils.sheetForMonth(m), 'carryover-salary'))} balance(stock)=${await cell(m, 'leftover-stock')} overspent-prev=${await cell(m, 'last-month-overspent')}`,
      );
    }
    console.error('NEW MONTHS\n  ' + out.join('\n  '));
  });

  it('held funds, month by month', async () => {
    const ledger = new Ledger();
    await seedBoth(ledger);
    const show = async (label: string) => {
      const out: string[] = [];
      for (const m of ['2016-10', '2016-11', '2016-12']) {
