import re
p='packages/loot-core/src/server/budget/base.ts'
s=open(p).read()
old=s[s.index("export async function doTransfer(categoryIds, transferId) {"):s.index("export async function createBudget(months) {")]
new='''// Overspending is taken out of the next month's To Budget one category at a
// time, and only for categories that don't roll it over. Merged categories
// are charged on what they come to together, which can differ from what they
// were charged apart: one that was overspent next to one with money left
// nets out. Returns how much that charge changes for a month, read from the
// budget as it is before the merge.
function getMergedOverspendingChange(
  sheetName: string,
  categoryIds: string[],
  transferId: string,
): number {
  const value = (name: string) => sheet.get().getCellValueLoose(sheetName, name);

  let balance = 0;
  let overspentApart = 0;
  for (const id of categoryIds) {
    const leftover = number(value(`leftover-${id}`));
    balance += leftover;
    if (!value(`carryover-${id}`)) {
      overspentApart += Math.min(0, leftover);
    }
  }

  const overspentTogether = value(`carryover-${transferId}`)
    ? 0
    : Math.min(0, balance);
  return overspentTogether - overspentApart;
}

// Moves the budgeted amounts of the given categories to the one taking their
// place. In an envelope budget this leaves every month's To Budget as it was,
// and the remaining category with the balances of all of them added up.
export async function doTransfer(categoryIds, transferId) {
  // The balances read below have to be the ones the budget shows now
  await sheet.waitOnSpreadsheet();

