  // in February, as 1,150.00 + 260.00 did before.
  describe('merging a category into another', () => {
    async function mergeFoodIntoFun() {
      await runHandler(app.handlers['category-delete'], {
        id: 'food',
        transferId: 'fun',
      });
    }

    async function budgeted(category: string) {
      const amounts: number[] = [];
      for (const month of MONTHS) {
        amounts.push(await value(month, `budget-${category}`));
      }
      return amounts;
    }

    it('budgets exactly what was entered for both and nothing else', async () => {
      await mergeFoodIntoFun();

      expect(await budgeted('fun')).toEqual([40000, 40000, 0]);
      expect(await value('2024-01', 'total-budgeted')).toBe(-40000);
      expect(await value('2024-02', 'total-budgeted')).toBe(-40000);
      expect(await value('2024-03', 'total-budgeted')).toBe(0);
    });

    it('saves nothing for months where there was nothing to move', async () => {
      await mergeFoodIntoFun();
      await sheet.waitOnSpreadsheet();

      const rows = await db.all<{ month: number }>(
