      await mergeFoodIntoFun();

      expect(await balances('fun')).toEqual([1000, 21000, 21000]);
      expect(await toBudget()).toEqual([60000, 120000, 120000]);
      expect(await value('2024-01', 'total-spent')).toBe(-39000);
      expect(await value('2024-02', 'total-spent')).toBe(-20000);
    });

    it('keeps To Budget and the balances adding up to the same in every month', async () => {
      const before = [61000, 141000, 141000];
      const total = async () => {
        const fun = await balances('fun');
