      expect(await value('2024-01', 'buffered-selected')).toBe(60000);
      expect(await value('2024-02', 'buffered-selected')).toBe(100000);
      // 50.00 more in February, which food's overspending no longer takes
      expect(await toBudget()).toEqual([0, 20000, 120000]);
    });

    it('follows the remaining category when it rolls over its overspending', async () => {
