import * as db from '#server/db';
import { runHandler } from '#server/mutators';
import * as sheet from '#server/sheet';

import {
  copyPreviousMonth,
  getSheetValue,
  setBudget,
  setCategoryCarryover,
} from './actions';
import { app } from './app';
import * as budget from './base';

// The figures of a tracking budget worked out by hand, month by month. The
// expected amounts are written out rather than taken from the budget
// recalculating itself, which would agree with itself whether or not it is
// right.
//
//                     January              February            March
//   Sales             5,000 budgeted       5,000 budgeted      -
//                     5,200 received       4,800 received
//   Grants            200 budgeted         -                   -
//   Rent (premises)   1,000 / 1,000 spent  1,000 / 1,000       -
//   Power (premises)  120 / 150 spent      120 / 100           -
//                     = -30.00             = 20.00
//   Stock (trading)   1,500 / 1,400 spent  1,500 / 1,650       -
//                     = 100.00             = -150.00
//
//   Budgeted income   5,200.00             5,000.00            0
//   Received          5,200.00             4,800.00            0
//   Budgeted expenses 2,620.00             2,620.00            0
//   Spent             2,550.00             2,750.00            0
//   Projected savings 2,580.00             2,380.00            0
//   Saved             2,650.00             2,050.00            0
//
// Nothing carries from one month to the next unless a category rolls over.

const MONTHS = ['2024-01', '2024-02', '2024-03'];

async function loadBudget(months = MONTHS) {
  await sheet.loadSpreadsheet(db);
  sheet.get().meta().budgetType = 'tracking';
  await budget.createBudget(months);
}

async function value(month: string, cell: string) {
  await sheet.waitOnSpreadsheet();
  return getSheetValue(`budget${month.replace('-', '')}`, cell);
}

async function eachMonth(cell: string) {
  const amounts: number[] = [];
  for (const month of [...sheet.get().meta().createdMonths].sort()) {
    amounts.push(await value(month, cell));
  }
  return amounts;
}

async function summary(month: string) {
  return {
    budgetedIncome: await value(month, 'total-budget-income'),
    received: await value(month, 'total-income'),
    budgetedExpenses: await value(month, 'total-budgeted'),
    spent: await value(month, 'total-spent'),
    projectedSavings: await value(month, 'total-saved'),
    saved: await value(month, 'real-saved'),
  };
}

const JANUARY = {
  budgetedIncome: 520000,
  received: 520000,
  budgetedExpenses: 262000,
  spent: -255000,
  projectedSavings: 258000,
  saved: 265000,
};

const FEBRUARY = {
  budgetedIncome: 500000,
  received: 480000,
  budgetedExpenses: 262000,
  spent: -275000,
  projectedSavings: 238000,
  saved: 205000,
};

beforeEach(async () => {
  await global.emptyDatabase()();
  db.runQuery(
    "INSERT INTO preferences (id, value) VALUES ('budgetType', 'tracking')",
  );

  await db.insertAccount({ id: 'current', name: 'Current' });
  await db.insertCategoryGroup({ id: 'income', name: 'Income', is_income: 1 });
  for (const id of ['sales', 'grants']) {
    await db.insertCategory({
      id,
      name: id,
      cat_group: 'income',
      is_income: 1,
    });
  }
  await db.insertCategoryGroup({ id: 'premises', name: 'Premises' });
  await db.insertCategory({ id: 'rent', name: 'rent', cat_group: 'premises' });
  await db.insertCategory({
    id: 'power',
    name: 'power',
    cat_group: 'premises',
  });
  await db.insertCategoryGroup({ id: 'trading', name: 'Trading' });
  await db.insertCategory({ id: 'stock', name: 'stock', cat_group: 'trading' });

  for (const [date, amount, category] of [
    ['2024-01-05', 520000, 'sales'],
    ['2024-01-06', -100000, 'rent'],
    ['2024-01-07', -15000, 'power'],
    ['2024-01-08', -140000, 'stock'],
    ['2024-02-05', 480000, 'sales'],
    ['2024-02-06', -100000, 'rent'],
    ['2024-02-07', -10000, 'power'],
    ['2024-02-08', -165000, 'stock'],
  ] as const) {
    await db.insertTransaction({ date, amount, category, account: 'current' });
  }

  await loadBudget();

  for (const month of ['2024-01', '2024-02']) {
    await setBudget({ category: 'sales', month, amount: 500000 });
    await setBudget({ category: 'rent', month, amount: 100000 });
    await setBudget({ category: 'power', month, amount: 12000 });
    await setBudget({ category: 'stock', month, amount: 150000 });
  }
  await setBudget({ category: 'grants', month: '2024-01', amount: 20000 });
});

describe('Tracking budget balance', () => {
  it('starts from the figures worked out by hand', async () => {
    expect(await summary('2024-01')).toEqual(JANUARY);
    expect(await summary('2024-02')).toEqual(FEBRUARY);

    expect(await eachMonth('leftover-rent')).toEqual([0, 0, 0]);
    expect(await eachMonth('leftover-power')).toEqual([-3000, 2000, 0]);
    expect(await eachMonth('leftover-stock')).toEqual([10000, -15000, 0]);
    // Budgeted less received
    expect(await eachMonth('leftover-sales')).toEqual([-20000, 20000, 0]);
    expect(await eachMonth('leftover-grants')).toEqual([20000, 0, 0]);

    expect(await eachMonth('group-budget-premises')).toEqual([
      112000, 112000, 0,
    ]);
    expect(await eachMonth('group-sum-amount-premises')).toEqual([
      -115000, -110000, 0,
    ]);
    expect(await eachMonth('group-leftover-premises')).toEqual([
      -3000, 2000, 0,
    ]);
    expect(await eachMonth('total-leftover')).toEqual([7000, -13000, 0]);
  });

  describe('rolling over', () => {
    const LATER_MONTHS = [...MONTHS, '2024-04', '2024-05'];

    beforeEach(async () => {
      await setCategoryCarryover({
        startMonth: '2024-01',
        category: 'power',
        flag: true,
      });
    });

    it('carries the balance of the category and changes no total', async () => {
      // -30.00 + 20.00, which then stays
      expect(await eachMonth('leftover-power')).toEqual([-3000, -1000, -1000]);
      expect(await eachMonth('group-leftover-premises')).toEqual([
        -3000, -1000, -1000,
      ]);
      expect(await summary('2024-01')).toEqual(JANUARY);
      expect(await summary('2024-02')).toEqual(FEBRUARY);
    });

    it('keeps rolling over in months added to the budget later', async () => {
      await budget.createBudget(LATER_MONTHS);

      expect(await eachMonth('leftover-power')).toEqual([
        -3000, -1000, -1000, -1000, -1000,
      ]);
    });

    it('keeps rolling over once something is budgeted in such a month', async () => {
      await budget.createBudget(LATER_MONTHS);
      await setBudget({ category: 'power', month: '2024-04', amount: 400 });
      await sheet.waitOnSpreadsheet();

      expect(await eachMonth('leftover-power')).toEqual([
        -3000, -1000, -1000, -600, -600,
      ]);

      sheet.unloadSpreadsheet();
      await loadBudget(LATER_MONTHS);
      expect(await eachMonth('leftover-power')).toEqual([
        -3000, -1000, -1000, -600, -600,
      ]);
    });
  });

  describe('hiding', () => {
    it('leaves a hidden category out of its group and the month', async () => {
      await db.update('categories', { id: 'power', hidden: 1 });

      expect(await value('2024-01', 'group-budget-premises')).toBe(100000);
      expect(await value('2024-01', 'group-sum-amount-premises')).toBe(-100000);
      expect(await summary('2024-01')).toEqual({
        ...JANUARY,
        budgetedExpenses: 250000,
        spent: -240000,
        projectedSavings: 270000,
        saved: 280000,
      });
    });

    it('keeps a hidden category out of the group it is moved to', async () => {
      await db.update('categories', { id: 'power', hidden: 1 });
      await db.moveCategory('power', 'trading', null);

      expect(await value('2024-01', 'group-budget-trading')).toBe(150000);
      expect(await value('2024-01', 'total-budgeted')).toBe(250000);

      await db.update('categories', { id: 'power', hidden: 0 });
      expect(await value('2024-01', 'group-budget-trading')).toBe(162000);
      expect(await value('2024-01', 'group-budget-premises')).toBe(100000);
      expect(await summary('2024-01')).toEqual(JANUARY);
    });

    it('leaves a hidden group out of the month', async () => {
      await db.update('category_groups', { id: 'trading', hidden: 1 });

      expect(await summary('2024-01')).toEqual({
        ...JANUARY,
        budgetedExpenses: 112000,
        spent: -115000,
        projectedSavings: 408000,
        saved: 405000,
      });

      await db.update('category_groups', { id: 'trading', hidden: 0 });
      expect(await summary('2024-01')).toEqual(JANUARY);
    });

    it('never counts income as an expense when the income group is hidden and shown', async () => {
      await db.update('category_groups', { id: 'income', hidden: 1 });
      await db.update('category_groups', { id: 'income', hidden: 0 });

      expect(await summary('2024-01')).toEqual(JANUARY);
      expect(await summary('2024-02')).toEqual(FEBRUARY);
    });
  });

  describe('merging a category into another', () => {
    it('adds up what was budgeted and spent and changes no total', async () => {
      await runHandler(app.handlers['category-delete'], {
        id: 'power',
        transferId: 'rent',
      });

      expect(await eachMonth('budget-rent')).toEqual([112000, 112000, 0]);
      expect(await eachMonth('sum-amount-rent')).toEqual([-115000, -110000, 0]);
      expect(await eachMonth('leftover-rent')).toEqual([-3000, 2000, 0]);
      expect(await summary('2024-01')).toEqual(JANUARY);
      expect(await summary('2024-02')).toEqual(FEBRUARY);
    });

    it('moves budgeted income to the income category taking its place', async () => {
      await runHandler(app.handlers['category-delete'], {
        id: 'grants',
        transferId: 'sales',
      });

      // 5,000.00 + 200.00 budgeted against 5,200.00 received
      expect(await eachMonth('budget-sales')).toEqual([520000, 500000, 0]);
      expect(await eachMonth('leftover-sales')).toEqual([0, 20000, 0]);
      expect(await summary('2024-01')).toEqual(JANUARY);
      expect(await summary('2024-02')).toEqual(FEBRUARY);
    });

    it('changes no total when a group is deleted into another category', async () => {
      await runHandler(app.handlers['category-group-delete'], {
        id: 'premises',
        transferId: 'stock',
      });

      expect(await eachMonth('budget-stock')).toEqual([262000, 262000, 0]);
      expect(await eachMonth('leftover-stock')).toEqual([7000, -13000, 0]);
      expect(await summary('2024-01')).toEqual(JANUARY);
      expect(await summary('2024-02')).toEqual(FEBRUARY);
    });
  });

  describe("copying last month's budget", () => {
    it('gives the month exactly what was budgeted the month before', async () => {
      // Nothing was budgeted for grants in February
      await setBudget({ category: 'grants', month: '2024-03', amount: 7000 });

      await copyPreviousMonth({ month: '2024-03' });

      expect(await value('2024-03', 'budget-grants')).toBe(0);
      expect(await value('2024-03', 'total-budget-income')).toBe(500000);
