export function createSummary(groups, categories, prevSheetName, sheetName) {
export function createBudget(meta, categories, months) {
  // The spreadsheet is now strict - so we need to fill in some
  // default values for the month before the first month. Only do this
  // if it doesn't already exist
  const blankSheet = getBlankSheet(months);
  if (meta.blankSheet !== blankSheet) {
    sheet.get().clearSheet(meta.blankSheet);
    createBlankMonth(categories, blankSheet, months);
    meta.blankSheet = blankSheet;
  }
}

export function handleCategoryChange(months, oldValue, newValue) {
  type Deps = Array<[string, string[]]>;

  // The cells totalling the categories of a group
  function getGroupDeps(groupId, cat): Deps {
    return [
      [`group-sum-amount-${groupId}`, [`sum-amount-${cat.id}`]],
      [`group-budget-${groupId}`, [`budget-${cat.id}`]],
      [`group-leftover-${groupId}`, [`leftover-${cat.id}`]],
    ];
  }

  // The cells totalling every category, whichever group it is in
  function getSummaryDeps(sheetName, prevSheetName, cat): Deps {
    if (cat.is_income) {
      return [
        [
          'buffered-auto',
          [
            `${sheetName}!sum-amount-${cat.id}`,
            `${sheetName}!carryover-${cat.id}`,
          ],
        ],
      ];
    }

    return [
      [
        'last-month-overspent',
        [
          `${prevSheetName}!leftover-${cat.id}`,
          `${prevSheetName}!carryover-${cat.id}`,
        ],
      ],
    ];
  }

  function addDeps(sheetName, deps: Deps) {
    deps.forEach(([cellName, cellDeps]) => {
      sheet.get().addDependencies(sheetName, cellName, cellDeps);
    });
  }

  function removeDeps(sheetName, deps: Deps) {
    deps.forEach(([cellName, cellDeps]) => {
      sheet.get().removeDependencies(sheetName, cellName, cellDeps);
    });
  }

  // Several changes to a category can arrive at once: a sync delivers
  // everything another device did since the last one, so a category can be
  // both moved and deleted here. Compare where it was counted with where it
  // belongs now instead of handling one kind of change.
  const wasAlive = oldValue != null && oldValue.tombstone === 0;
  const isAlive = newValue.tombstone === 0;
  const hasMoved =
    wasAlive && isAlive && oldValue.cat_group !== newValue.cat_group;

  if (wasAlive === isAlive && !hasMoved) {
    return;
  }

  if (isAlive && !wasAlive) {
    createBlankCategory(newValue, months);
  }

  // Oldest first: a month's cells can depend on the month before it
  [...(months as Set<string>)].sort().forEach(month => {
    const prevMonth = monthUtils.prevMonth(month);
    const prevSheetName = monthUtils.sheetForMonth(prevMonth);
    const sheetName = monthUtils.sheetForMonth(month);
    const summaryDeps = getSummaryDeps(sheetName, prevSheetName, newValue);

    if (wasAlive) {
      // It was counted in the group it was in before this change, which
      // isn't the group it has now if it also moved
      removeDeps(sheetName, getGroupDeps(oldValue.cat_group, newValue));

      if (!isAlive) {
        removeDeps(sheetName, summaryDeps);
      }
    } else {
      const { start, end } = monthUtils.bounds(month);
      createCategoryFromBase(newValue, sheetName, prevSheetName, start, end);

      addDeps(sheetName, summaryDeps);
    }

    if (isAlive) {
      addDeps(sheetName, getGroupDeps(newValue.cat_group, newValue));
    }
  });
}

